/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A58 staging patch: exact frozen manifest Japanese–krypton (80 entries). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs});
P('Japanese','Japanese 由 Japan 加 -ese 构成，可作名词指日本人或日语，也可作形容词表示日本的。',[C('Japanese.s1','人物与国籍','A Japanese joined the exchange group and described how her hometown celebrates the spring festival.','一位日本人加入了交流小组，并介绍家乡如何庆祝春季节日。','A Japanese joined the exchange group / and described how her hometown celebrates / the spring festival.','Japanese 作可数名词时指一名日本人；A Japanese 后接单数谓语 joined。','句子中的人来自日本。'),C('Japanese.s2','语言学习','The guide spoke Japanese with the station staff to confirm which train stopped at the coastal village.','导游用日语与车站工作人员交谈，确认哪班火车停靠海边村庄。','The guide spoke Japanese with the station staff / to confirm / which train stopped at the coastal village.','Japanese 作名词指日语；to confirm 表示交谈目的。','导游使用的语言是日语。'),C('Japanese.s3','文化与设计','The exhibit compares Japanese ceramics with pottery from several neighboring countries.','展览把日本陶瓷与几个邻国的陶器作比较。','The exhibit compares Japanese ceramics / with pottery / from several neighboring countries.','Japanese 作形容词修饰 ceramics，表示日本的。','该词描述陶瓷的来源或文化关联。')],M('A Japanese person spoke Chinese in the station, so the sentence says she spoke the Japanese language.','A Japanese person spoke Japanese in the station, so the sentence names the language correctly.','若句子要表达所用语言，应写 spoke Japanese；Japanese person 是人物国籍短语。','word-choice'),[Q('Japanese',1,1,'In “A Japanese joined the group,” Japanese refers to?','a person from Japan','the language spoken in Japan','a ceramic bowl','s1 指日本人。'),Q('Japanese',2,2,'The guide spoke Japanese. What did the guide speak?','the language spoken in Japan','a train line','a type of pottery','s2 指日语。'),Q('Japanese',3,3,'In “Japanese ceramics,” Japanese is?','an adjective meaning relating to Japan','a noun meaning a train station','a verb meaning to exchange','s3 作形容词表示日本的。'),Q('Japanese',4,1,'Which sentence uses Japanese as a person noun?','A Japanese greeted the visitors.','She studied Japanese grammar.','They displayed Japanese pottery.','第一句中 Japanese 指一名日本人。')]);
P('jasmine','Jasmine 经法语和阿拉伯语源自波斯语 yasamin，指以芬芳花朵闻名的茉莉植物，也指用于茶或香水的茉莉花。',C('jasmine.s1','植物与香气','The jasmine climbed along the courtyard wall, and its white flowers scented the evening air.','茉莉沿着庭院墙攀爬，白花让夜晚的空气带上香气。','The jasmine climbed along the courtyard wall / and its white flowers scented / the evening air.','jasmine 指开芳香花朵的植物；and 连接生长状态与香气效果。','攀爬生长并开香花符合茉莉特征。'),M('The jasmine filled the courtyard with fragrance even though the plant had no flowers or scent.','The jasmine filled the courtyard with fragrance when its scented flowers opened.','没有花香的植物不能使庭院弥漫茉莉香。'),[Q('jasmine',1,1,'Jasmine is a plant known for?','fragrant flowers','metal ingots','a harsh call','茉莉以芳香花朵著称。'),Q('jasmine',2,1,'What did the jasmine do along the wall?','climb and produce scented flowers','grow as a deep-rooted conifer','sting visitors with its arms','茉莉可以攀爬并开香花。'),Q('jasmine',3,1,'Jasmine flowers may be used in?','tea or perfume','steel production','road traffic signals','茉莉花常用于茶和香水。'),Q('jasmine',4,1,'Which detail best identifies jasmine?','a plant with fragrant flowers','a bird with a harsh call','a dried strip of meat','芳香花朵是茉莉的标志。')]);
P('jawbone','Jawbone 由 jaw 与 bone 组成，可作名词指构成下颌的骨头，也可作动词表示以强硬言辞劝说或施压。',[C('jawbone.s1','解剖与身体','The scan showed a small fracture in the lower jawbone, so the dentist recommended a follow-up examination.','扫描显示下颌骨有一处小骨折，因此牙医建议复查。','The scan showed a small fracture / in the lower jawbone / so the dentist recommended a follow-up examination.','jawbone 作名词指构成颌部的骨骼；in 标出骨折位置。','骨折发生在下颌骨上。'),C('jawbone.s2','谈判与施压','The governor tried to jawbone the suppliers into lowering prices by warning that public contracts might be reconsidered.','州长试图通过警告可能重新审议公共合同，施压供应商降低价格。','The governor tried to jawbone the suppliers into lowering prices / by warning / that public contracts might be reconsidered.','jawbone 作动词表示通过强硬谈话劝说或施压；into 后接被说服采取的行动。','公开警告合同可能被重新考虑，是施压手段。')],M('The scan showed a fracture in the jawbone, but the jawbone is a soft muscle rather than a bone.','The scan showed a fracture in the jawbone, which is one of the bones forming the jaw.','jawbone 指颌部骨骼，不是肌肉。','word-choice'),[Q('jawbone',1,1,'A jawbone is?','one of the bones that form the jaw','a soft muscle of the shoulder','a small songbird','s1 指颌骨。'),Q('jawbone',2,2,'To jawbone suppliers into lowering prices is to?','try to persuade or pressure them through forceful talk','measure the suppliers’ jaw bones','sign a contract without speaking','s2 指通过谈话施压。'),Q('jawbone',3,1,'Where might a dentist find a jawbone fracture?','in one of the bones of the jaw','in a bird’s wing','in a metal railing','下颌骨是牙科检查区域的骨骼。'),Q('jawbone',4,2,'Which action shows jawboning?','a public official pressures a company through forceful statements','a doctor scans a patient’s jaw','a supplier lowers prices without discussion','公开强硬劝说供应商属于动词义。')]);
P('jay','Jay 是鸟名，可能经古法语 jai 进入英语，指一种中等大小、叫声粗厉的鸦科鸟类，如欧亚松鸦。',C('jay.s1','鸟类观察','A jay gave a harsh call from the oak tree before flying across the garden with an acorn in its beak.','一只松鸦在橡树上发出粗厉叫声，随后叼着橡果飞过花园。','A jay gave a harsh call from the oak tree / before flying across the garden / with an acorn in its beak.','jay 是鸟类名词；before 引出飞走前发生的动作。','粗厉叫声和叼橡果的行为符合松鸦形象。'),M('The jay was a quiet fish that swam beneath the oak tree.','The jay was a bird that called from the oak tree.','jay 指鸟类，不是鱼。','word-choice'),[Q('jay',1,1,'A jay is a kind of?','medium-sized corvid bird','marine mammal','metal block','jay 指松鸦一类的鸦科鸟。'),Q('jay',2,1,'What did the jay carry in its beak?','an acorn','a train ticket','a jar of kerosene','松鸦叼着橡果飞行。'),Q('jay',3,1,'Which sound may a jay make?','a harsh call','a human-language sentence','a low-frequency infrasound only','松鸦常发出粗厉叫声。'),Q('jay',4,1,'Which animal could be called a jay?','a corvid in an oak tree','a jellyfish in the sea','a kangaroo in a field','jay 是鸦科鸟。')]);
P('jaywalk','Jaywalk 由 jay 与 walk 组合而成，原指像乡下笨汉般不守规矩，现代表示在不允许或不安全处横穿马路。',C('jaywalk.s1','道路安全','The officer stopped a pedestrian who tried to jaywalk between two parked buses instead of using the marked crossing.','一名行人试图在两辆停靠的公交车之间违规横穿，警员将其拦下并提醒走斑马线。','The officer stopped a pedestrian / who tried to jaywalk between two parked buses / instead of using the marked crossing.','jaywalk 表示在不允许或不安全处横穿道路；instead of 对比安全替代方式。','行人没有使用标记的人行横道。'),M('The pedestrian jaywalked by using the marked crosswalk when the signal allowed her to cross.','The pedestrian crossed legally by using the marked crosswalk when the signal allowed her to cross.','使用开放的标记人行横道是合法过街，不是 jaywalk。','word-choice'),[Q('jaywalk',1,1,'To jaywalk is to?','cross a road where it is not allowed or safe','walk carefully along a sidewalk','wait for a green pedestrian signal at a crossing','jaywalk 指违规或危险地横穿道路。'),Q('jaywalk',2,1,'Why did the officer stop the pedestrian?','she crossed between buses instead of using the crossing','she waited at the marked crosswalk','she walked inside a bus station','在车辆之间横穿存在危险。'),Q('jaywalk',3,1,'Which action is jaywalking?','crossing mid-block where crossing is prohibited','using a marked crosswalk on a walk signal','walking along the pavement','禁止处横穿马路属于违规行为。'),Q('jaywalk',4,1,'What is the safer alternative to jaywalking?','use a marked pedestrian crossing','cross between parked buses','run into the road without checking','使用标记人行横道更安全。')]);
P('jealously','Jealously 由 jealous 加 -ly 构成，可表示因羡慕他人而嫉妒地，也可表示戒备地守护不愿失去的权利或秘密。',[C('jealously.s1','嫉妒与比较','Nora watched her colleague receive praise jealously, wishing she had earned the recognition herself.','诺拉嫉妒地看着同事受到表扬，心想自己也希望获得那份认可。','Nora watched her colleague receive praise jealously / wishing / she had earned the recognition herself.','jealously 修饰 watched，表示因羡慕他人所得而嫉妒；wishing 补充她的心情。','她羡慕同事得到表扬，体现嫉妒义。'),C('jealously.s2','保护与占有','The archivist guarded the original letters jealously and allowed researchers to handle only digital copies.','档案员戒备地守护原始信件，只允许研究者查看数字副本。','The archivist guarded the original letters jealously / and allowed researchers / to handle only digital copies.','jealously 修饰 guarded，表示严密保护、唯恐失去；and 引出限制接触的措施。','对原件的严格保护体现戒备义。')],M('The archivist guarded the letters jealously by leaving them unattended in an open hallway.','The archivist guarded the letters carelessly by leaving them unattended in an open hallway.','将信件无人看管地放在走廊不符合戒备守护。','word-choice'),[Q('jealously',1,1,'To watch someone jealously may mean to watch them?','with envy of their advantages','with no awareness of their success','because they are in jeopardy','s1 指嫉妒地。'),Q('jealously',2,2,'To guard a secret jealously is to?','protect it carefully because you do not want to lose it','share it publicly with everyone','forget where it is stored','s2 指严密保护。'),Q('jealously',3,1,'Why did Nora watch her colleague jealously?','she wished she had received the praise','she had no interest in recognition','she was safeguarding the archive','嫉妒来自羡慕对方得到认可。'),Q('jealously',4,2,'Which action shows guarding something jealously?','keeping the original letters secure and limiting access','leaving them unattended in public','giving every visitor an original','严格限制原件接触体现保护义。')]);
P('jean','Jean 是一种耐磨棉斜纹布的名称，词源常与欧洲早期纺织贸易和意大利热那亚（法语 Gênes）联系起来。',C('jean.s1','纺织与服装','The work trousers were cut from sturdy jean, a cotton twill that could withstand repeated washing.','这条工装裤用耐磨牛仔布裁制，可承受反复清洗。','The work trousers were cut from sturdy jean / a cotton twill / that could withstand repeated washing.','jean 指耐用的棉斜纹布；that 从句说明这种布料的特点。','耐磨棉斜纹布适合制作工装。'),M('The trousers were made of jean, a delicate silk that tore after one gentle wash.','The trousers were made of a sturdy cotton twill that could withstand repeated washing.','牛仔斜纹布耐磨，并非轻柔易破的丝绸。','word-choice'),[Q('jean',1,1,'Jean is a type of?','hard-wearing cotton twill fabric','soft glass used in windows','a species of bird','jean 指耐磨棉斜纹布。'),Q('jean',2,1,'Why use jean for work trousers?','it can withstand repeated wear and washing','it tears after one gentle wash','it is a liquid fuel','耐磨特性适合工装。'),Q('jean',3,1,'Which description fits jean?','a durable twill cotton','a delicate silk thread','an animal’s jawbone','jean 是结实的棉斜纹布。'),Q('jean',4,1,'Jean is most closely associated with?','denim-like cotton fabric','a road-crossing offense','a legal court order','jean 是一种棉布料。')]);
P('jeer','Jeer 词源说法并不完全确定；英语中作动词表示大声讥笑，也可作名词指一句嘲弄的话或嘲笑声。',[C('jeer.s1','嘲笑与反应','Several spectators jeered at the runner after he stumbled, but the coach urged them to show respect.','跑者绊倒后，几名观众大声嘲笑他，但教练劝他们保持尊重。','Several spectators jeered at the runner / after he stumbled / but the coach urged them to show respect.','jeer at someone 作动词，表示大声嘲笑；but 引出教练的反对态度。','观众喊出嘲弄话语。'),C('jeer.s2','言语与嘲弄','One jeer from the back row interrupted the speaker, who paused until the room became quiet.','后排传来一句嘲讽，打断了演讲者；他停下来，直到房间安静。','One jeer from the back row interrupted the speaker / who paused / until the room became quiet.','jeer 作名词指嘲笑的话语或声音；one 限定为一句。','一句嘲弄打断讲话，体现名词义。')],M('The audience jeered at the speaker by applauding respectfully and encouraging her to continue.','The audience applauded the speaker respectfully and encouraged her to continue.','尊敬地鼓掌支持与 jeer 嘲笑相反。','word-choice'),[Q('jeer',1,1,'To jeer at someone is to?','shout rude remarks to mock them','offer sincere praise','ask a respectful question','jeer 作动词表示嘲笑。'),Q('jeer',2,2,'A jeer from the crowd is?','a loud rude remark or mocking sound','a written dedication in a book','an informative explanation','jeer 作名词指嘲弄声。'),Q('jeer',3,1,'Why did the coach object when spectators jeered?','they mocked a runner who had stumbled','they offered respectful encouragement','they asked for an in-depth interview','观众嘲笑失误的跑者，行为不尊重。'),Q('jeer',4,2,'Which is a jeer?','a shouted taunt aimed at a performer','a quiet thank-you note','a warning bell rung for a funeral','大声嘲弄属于 jeer。')]);
P('jellyfish','Jellyfish 是 jelly 与 fish 组成的复合词，指有柔软伞状身体和带刺触手的海洋动物；贬义口语中也可指软弱、拿不定主意的人。',[C('jellyfish.s1','海洋生物','A jellyfish drifted near the pier, its soft body pulsing as the current carried it toward deeper water.','一只水母漂到码头附近，柔软身体一张一缩，随水流移向深水。','A jellyfish drifted near the pier / its soft body pulsing / as the current carried it toward deeper water.','jellyfish 指海洋动物水母；as 引出水流带动它移动的情况。','水母柔软身体随水流漂动。'),C('jellyfish.s2','口语评价','In the play, one character calls the indecisive mayor a jellyfish for refusing to take a position.','剧中一个角色把不果断的市长称作“软弱的人”，因为他不肯表明立场。','In the play / one character calls the indecisive mayor a jellyfish / for refusing to take a position.','jellyfish 作贬义比喻名词，指软弱无决断的人；for 引出责骂原因。','拒绝作决定体现该口语贬义。','register')],M('The jellyfish stung the swimmer with its soft tentacles and became a weak indecisive person.','The indecisive politician was called a jellyfish as an insult.','海洋动物义和贬义人物义属于不同语境，不能混为一谈。','meaning'),[Q('jellyfish',1,1,'A sea jellyfish has?','a soft body and stinging arms','a hard metal shell','a jawbone and feathers','s1 指身体柔软并有刺腕的海洋动物。'),Q('jellyfish',2,2,'Calling a politician a jellyfish is an insult meaning the person is?','weak and unable to make firm decisions','a skilled ocean animal','highly informative','s2 是软弱无决断的贬义比喻。'),Q('jellyfish',3,1,'Where would you usually see a jellyfish?','in the sea','in a jewelry shop','inside a computer','水母是海洋动物。'),Q('jellyfish',4,2,'Why did the character call the mayor a jellyfish?','he refused to take a position','he swam near the pier','he wrote a memoir','拒绝表态被比喻为软弱无决断。')]);
P('jeopardy','Jeopardy 来自古法语 jeu parti“分胜负的游戏”，引申为危险处境；也可指有价值的事业或成果面临失去的风险。',[C('jeopardy.s1','安全与危险','The hikers’ lives were in jeopardy after the river rose and blocked the only route back to camp.','河水上涨并挡住返回营地的唯一道路后，徒步者的生命陷入危险。','The hikers’ lives were in jeopardy / after the river rose / and blocked the only route back to camp.','in jeopardy 表示处于危险中；after 引出生命安全受威胁的原因。','回营地道路被阻断，徒步者遭遇危险。'),C('jeopardy.s2','事业与损失风险','Repeated data errors put the research grant in jeopardy because the sponsor could withdraw funding.','数据反复出错使研究资助岌岌可危，因为赞助方可能撤回资金。','Repeated data errors put the research grant in jeopardy / because the sponsor could withdraw funding.','put something in jeopardy 表示使某项成果面临失去的风险；because 说明可能后果。','资助可能被撤回，说明研究项目面临损失风险。')],M('The hikers’ lives were in jeopardy because the river was low and every route back was safe and open.','The hikers were safe because the river was low and every route back was open.','道路畅通且河水低，不构成危险处境。','word-choice'),[Q('jeopardy',1,1,'A person in jeopardy is?','in danger of being harmed','certain to receive an award','already safely at home','s1 指危险处境。'),Q('jeopardy',2,2,'A research grant is in jeopardy if?','the sponsor may withdraw its funding','the funding has been guaranteed permanently','the project has already ended successfully','s2 指成果或事业面临失去风险。'),Q('jeopardy',3,1,'Why were the hikers in jeopardy?','the rising river blocked their only route to camp','the path was clear and the water was low','they had already returned safely','河水上涨且道路被阻，带来危险。'),Q('jeopardy',4,2,'Repeated data errors put the grant in jeopardy because?','they threatened continued funding','they secured funding forever','they moved the research to an island','错误可能使赞助方撤资。')]);
P('jerky','Jerky 可作形容词，来自 jerk“猛动”，形容短促突兀、不平顺的动作；作名词则指切片腌制并风干的瘦肉。',[C('jerky.s1','动作与运动','The camera footage showed the robot making jerky movements as it struggled to balance on the uneven floor.','录像显示机器人在不平地面上难以保持平衡，动作一顿一顿的。','The camera footage showed the robot making jerky movements / as it struggled / to balance on the uneven floor.','jerky 修饰 movements，表示短促突兀、不平顺；as 引出原因。','动作因平衡困难而不连贯。'),C('jerky.s2','食品与保存','The hikers packed beef jerky because the dried meat was light to carry and did not need refrigeration during the trip.','徒步者带了牛肉干，因为这种干肉便于携带，旅途中也不需要冷藏。','The hikers packed beef jerky / because the dried meat was light to carry / and did not need refrigeration during the trip.','jerky 作名词指腌制风干的肉；because 说明携带理由。','风干肉轻便且易保存。')],M('The robot made jerky movements, meaning it moved in a smooth continuous glide without any sudden stops.','The robot moved smoothly, without the jerks shown in the footage.','平滑连贯的运动与 jerky 的突兀不顺相反。','word-choice'),[Q('jerky',1,1,'A jerky movement is?','short, sudden, and not smooth','steady and perfectly fluid','a type of fragrant flower','s1 指一顿一顿的动作。'),Q('jerky',2,2,'Beef jerky is?','thin meat that has been salted and dried','a soft fruit eaten fresh','a sea animal with stinging arms','s2 指肉干。'),Q('jerky',3,1,'Why did the robot look jerky on the uneven floor?','it made abrupt movements while trying to balance','it moved in a smooth glide','it was a piece of dried meat','机器人失衡时动作突兀。'),Q('jerky',4,2,'Which food is jerky?','dried seasoned meat packed for a hike','fresh jasmine tea','a ceramic insulator','腌制风干肉属于 jerky。')]);
P('jettison','Jettison 经法语 jeter“投掷”相关形式进入英语，原指遇险时把货物抛出减轻船重，现也可表示丢弃物品或放弃计划。',[C('jettison.s1','清理与丢弃','The crew jettisoned damaged supplies that could no longer be used, making room for fresh water.','船员丢弃了无法再用的损坏物资，为淡水腾出空间。','The crew jettisoned damaged supplies / that could no longer be used / making room for fresh water.','jettison 作动词表示丢掉不再需要的东西；making room 说明目的。','损坏物资被抛弃以腾出空间。'),C('jettison.s2','计划与观念','The design team jettisoned its first plan after testing showed that the bridge would be too narrow for emergency vehicles.','测试显示桥梁太窄，消防救援车辆无法通行后，设计团队放弃了最初方案。','The design team jettisoned its first plan / after testing showed / that the bridge would be too narrow for emergency vehicles.','jettison 可表示放弃计划或想法；after 引出放弃计划的依据。','方案存在安全问题，因此被舍弃。'),C('jettison.s3','航海与货物','In the old logbook, the captain recorded the jettison of cargo during a storm to keep the ship afloat.','在旧航海日志中，船长记录了风暴期间抛弃货物以保持船只漂浮的行动。','In the old logbook / the captain recorded the jettison of cargo / during a storm to keep the ship afloat.','jettison 作名词指危险中被抛弃的货物；of cargo 说明抛弃对象。','船上货物在风暴中被抛出以减轻船重。')],M('The crew jettisoned unwanted supplies by carefully storing every one of them for future use.','The crew kept the useful supplies and jettisoned the damaged items they no longer needed.','保留全部物资与丢弃不需要物资相反。','word-choice'),[Q('jettison',1,1,'To jettison unwanted supplies is to?','get rid of them','repair them for later use','measure them in kilos','s1 指丢弃。'),Q('jettison',2,2,'A team jettisons a plan when it?','abandons the plan','installs it unchanged','publishes it as a journalist','s2 指放弃方案。'),Q('jettison',3,3,'In a ship’s log, a jettison of cargo is?','goods thrown overboard to lighten the vessel','a payment made to a jeweler','an order to install a keel','s3 指危险中抛弃的货物。'),Q('jettison',4,1,'Why did the crew jettison damaged supplies?','they were unusable and took up space','they were essential and in good condition','the crew wanted more damaged items','丢弃坏物资能腾出空间。')]);
P('jeweler','Jeweler 由 jewel 加表示职业的 -er 构成，指制作或销售珠宝首饰的人。',C('jeweler.s1','职业与手艺','The jeweler adjusted the ring’s setting under a magnifying lens before returning it to the customer.','珠宝匠在放大镜下调整戒指的镶嵌座，然后把戒指交还给顾客。','The jeweler adjusted the ring’s setting / under a magnifying lens / before returning it to the customer.','jeweler 指制作或销售珠宝首饰的人；before 表示交还前的修理步骤。','调整戒指镶嵌座属于珠宝匠的工作。'),M('The jeweler repaired the ring even though she was a bird that nested on a cliff.','The kestrel nested on a cliff, while the jeweler repaired the ring.','珠宝匠是从事珠宝业的人，不是鸟类。','word-choice'),[Q('jeweler',1,1,'A jeweler is someone who?','makes or sells jewelry','studies infrasound','builds a wooden door','jeweler 指珠宝匠或珠宝商。'),Q('jeweler',2,1,'What did the jeweler adjust?','the setting of a customer’s ring','the keel of a boat','a train’s timetable','珠宝匠修理戒指镶嵌座。'),Q('jeweler',3,1,'Where might you find a jeweler at work?','in a shop displaying rings and necklaces','in a kennel boarding dogs','in a greenhouse growing jasmine','珠宝商常在首饰店工作。'),Q('jeweler',4,1,'Jeweler is derived from which noun?','jewel','jeer','jogging','jeweler 由 jewel 加职业后缀构成。')]);
P('jewellery','Jewellery 是英式拼法，作为集合名词指佩戴在身上的装饰性首饰，如戒指、项链或耳环。',C('jewellery.s1','首饰与穿戴','She kept her grandmother’s jewellery in a lined box, including a silver brooch and two small rings.','她把祖母留下的首饰放在衬垫盒里，其中有一枚银胸针和两枚小戒指。','She kept her grandmother’s jewellery in a lined box / including a silver brooch / and two small rings.','jewellery 是集合名词，统指佩戴装饰品；including 举例说明首饰种类。','胸针和戒指都属于 jewellery。','英式拼法；美式常写 jewelry。'),M('The box contained jewellery, including a silver brooch and rings, but none of the objects were decorative items worn on the body.','The box contained jewellery, including a silver brooch and rings worn as decoration.','胸针和戒指是佩戴的装饰品。','meaning'),[Q('jewellery',1,1,'Jewellery is?','decorative objects worn on the body','a type of dried meat','a legal order','jewellery 指珠宝首饰。'),Q('jewellery',2,1,'Which item belongs to someone’s jewellery?','a silver brooch','a steel ingot','a dog kennel','胸针是首饰。'),Q('jewellery',3,1,'Jewellery is commonly written this way in?','British English','only Japanese','infrasound science','jewellery 是英式拼法。'),Q('jewellery',4,1,'Jewellery and jewelry are?','British and American spellings of the same word','two words with opposite meanings','the names of two birds','两种拼法均正确。')]);
P('jewelry','Jewelry 是美式拼法，作集合名词指戒指、项链等装饰性首饰，也可指珠宝店出售的首饰货品。',[C('jewelry.s1','装饰与佩戴','The museum displayed silver jewelry that had been worn at weddings in the coastal town.','博物馆展示了曾在海滨小镇婚礼上佩戴的银首饰。','The museum displayed silver jewelry / that had been worn at weddings / in the coastal town.','jewelry 指供佩戴的装饰性首饰；that 从句补充其使用场合。','银首饰曾作为婚礼装饰佩戴。'),C('jewelry.s2','商店商品','The jewelry shop placed its new gemstone pieces in a locked case near the entrance.','珠宝店把新到的宝石首饰放进入口附近的上锁展柜。','The jewelry shop placed its new gemstone pieces / in a locked case / near the entrance.','jewelry 可指珠宝店出售的商品；new gemstone pieces 是具体货品。','宝石首饰陈列在店内展柜中。')],M('The shop’s jewelry was displayed in the case, but it consisted only of kitchen pans and no decorative pieces.','The shop’s kitchenware was displayed in the case, while its jewelry consisted of decorative pieces.','锅具属于 kitchenware，不是 jewelry。','word-choice'),[Q('jewelry',1,1,'Jewelry is?','decorative objects such as rings and necklaces','equipment for cooking food','a harsh call from a bird','jewelry 指珠宝首饰。'),Q('jewelry',2,2,'In a jewelry shop, jewelry may mean?','the fine pieces sold there','the shop’s heating system','the act of crossing a road unlawfully','s2 指店内出售的首饰货品。'),Q('jewelry',3,1,'Which item is jewelry?','a necklace worn for decoration','a frying pan used for cooking','a ceramic electrical fitting','项链是首饰。'),Q('jewelry',4,1,'Jewelry is the common American spelling of British?','jewellery','jeweler','jibe','jewelry 是美式拼法。')]);
P('jewett','Jewett 是英语姓氏，著名使用者包括描写新英格兰海岸生活的作家 Sarah Orne Jewett。',C('jewett.s1','姓名与文学','The class read a coastal story by Sarah Orne Jewett and discussed how its setting shaped the characters.','全班阅读了 Sarah Orne Jewett 的一篇海岸题材故事，并讨论环境如何塑造人物。','The class read a coastal story by Sarah Orne Jewett / and discussed / how its setting shaped the characters.','Jewett 在此作姓氏，指作家 Sarah Orne Jewett；by 引出作品作者。','该姓氏对应一位新英格兰作家。'),M('The class read a story by Sarah Orne Jewett, treating Jewett as the name of a type of sea animal.','The class read a story by Sarah Orne Jewett, treating Jewett as the author’s surname.','Jewett 在此是作者姓氏，不是海洋动物名称。','word-choice'),[Q('jewett',1,1,'Jewett in “Sarah Orne Jewett” is?','a surname','a kind of jewelry','a legal command','该词条指姓氏。'),Q('jewett',2,1,'Sarah Orne Jewett is best known here as?','a writer about coastal New England','a Japanese language teacher','a jeweler in a shop','她是描写新英格兰海岸生活的作家。'),Q('jewett',3,1,'Which title would likely appear in a bibliography under Jewett?','a story by Sarah Orne Jewett','a manual on infrasound','a guide to kangaroo care','她的作品可列在 Jewett 姓下。'),Q('jewett',4,1,'In the name Sarah Orne Jewett, Jewett functions as?','the family name','the given name','the name of a bird','Jewett 是姓氏。')]);
P('jibe','Jibe 的词源有多种说法；现代可作动词表示与另一说法或事实相符，也可作名词指嘲讽的话。',[C('jibe.s1','证据与一致性','The witness’s account did not jibe with the security video, which showed the visitor entering through another door.','证人的说法与监控录像不符，录像显示访客是从另一扇门进入的。','The witness’s account did not jibe with the security video / which showed the visitor / entering through another door.','jibe with 表示与某事相符；did not 说明两者存在矛盾。','证词与录像显示的入口不同。'),C('jibe.s2','嘲讽与言语','One jibe about the novice’s accent made the room uncomfortable, so the instructor stopped the discussion.','有人嘲笑新手的口音，这句讥讽让房间气氛尴尬，教练于是中止讨论。','One jibe about the novice’s accent / made the room uncomfortable / so the instructor stopped the discussion.','jibe 作名词指嘲弄的话；about 引出讥讽对象。','嘲笑口音的言语使气氛难堪。')],M('The account jibed with the video even though the video clearly showed a different entrance.','The account conflicted with the video because it described a different entrance.','内容明显不同表示不一致。','word-choice'),[Q('jibe',1,1,'If an account jibes with a video, it?','agrees with what the video shows','mocks the person who made the video','measures the video in inches','s1 指相符。'),Q('jibe',2,2,'A jibe about someone’s accent is?','a mocking remark','a factual court order','a new jewelry design','s2 指讥讽的话。'),Q('jibe',3,1,'Why did the witness’s account fail to jibe with the video?','they described different entrances','they both showed the same door','the video contained no images','证词与视频内容相矛盾。'),Q('jibe',4,2,'Which sentence uses jibe as a noun?','He made a jibe about the player’s mistake.','Her story did not jibe with the records.','They installed a new camera.','第一句中 jibe 是名词“讥讽”。')]);
P('jobber','Jobber 是 job 加表示从事某种工作者的 -er，尤其指从生产者买入商品再转售给零售商的中间批发商。',C('jobber.s1','贸易与分销','The jobber bought boxes of fruit from growers and sold smaller quantities to neighborhood shops.','这位批发中间商从种植者处成箱买入水果，再分小批卖给社区商店。','The jobber bought boxes of fruit from growers / and sold smaller quantities / to neighborhood shops.','jobber 指生产者与零售商之间的批发商；from/to 标出交易链条。','先向种植者采购、再卖给零售店，符合中间商职责。'),M('The jobber sold fruit to growers after buying it from neighborhood retail shops.','The jobber bought fruit from growers and sold it to neighborhood retail shops.','jobber 的典型渠道方向是从生产者买入并转卖给零售商。','context'),[Q('jobber',1,1,'A jobber in trade is often?','a middleman who buys from producers and sells to retailers','a customer who buys one item for personal use','a journalist reporting on a court case','jobber 指批发中间商。'),Q('jobber',2,1,'Where did the jobber obtain the fruit?','from growers','from neighborhood shops after retail sale','from a jewelry display case','中间商直接向生产者采购。'),Q('jobber',3,1,'To whom did the jobber resell smaller quantities?','local shops','the growers who had just sold the fruit','the fruit trees','批发商把商品转售给零售店。'),Q('jobber',4,1,'Which role is closest to jobber here?','wholesale distributor','final consumer','farm laborer only','此处 jobber 接近批发分销商。')]);
P('jocose','Jocose 来自拉丁语 jocosus“爱开玩笑的”，形容某人爱说笑或某句话带着玩笑意味。',C('jocose.s1','幽默与语气','The jocose host greeted each guest with a light pun, keeping the formal dinner relaxed without embarrassing anyone.','这位爱开玩笑的主人用轻松双关语迎接宾客，让正式晚餐气氛放松，却没有使人难堪。','The jocose host greeted each guest with a light pun / keeping the formal dinner relaxed / without embarrassing anyone.','jocose 修饰 host，表示爱开玩笑；keeping 补充幽默带来的效果。','轻松玩笑营造愉快气氛且未冒犯他人。'),M('The jocose host never joked, smiled, or made any humorous remark throughout the evening.','The serious host never joked, smiled, or made any humorous remark throughout the evening.','完全不开玩笑的主人不是 jocose。','word-choice'),[Q('jocose',1,1,'A jocose person is?','given to jokes or playful remarks','usually hostile and insulting','a small bird of prey','jocose 指爱开玩笑的。'),Q('jocose',2,1,'Why was the host jocose?','he greeted guests with light puns','he refused to speak to anyone','he read a solemn legal order','轻松双关语体现幽默。'),Q('jocose',3,1,'Which comment is jocose?','a gentle playful pun at dinner','a cruel insult about a guest','a technical instruction for a kiln','轻松俏皮的双关语属于玩笑。'),Q('jocose',4,1,'Jocose is closest in meaning to?','humorous','insular','inorganic','jocose 与 humorous 接近。')]);
P('jogging','Jogging 由 jog 加 -ing 构成，指为健身而以轻松速度跑步的活动。',C('jogging.s1','运动与健身','Mina goes jogging along the river path three mornings a week to build endurance gradually.','米娜每周三个早晨沿河道慢跑，逐渐增强耐力。','Mina goes jogging along the river path / three mornings a week / to build endurance gradually.','jogging 作名词指健身慢跑；to build 说明慢跑目的。','规律轻松跑步用来增强耐力。'),M('Mina goes jogging by sitting motionless on the river path for an hour.','Mina goes jogging by running gently along the river path.','静坐不是慢跑。','word-choice'),[Q('jogging',1,1,'Jogging is?','running gently for exercise','walking without moving at all','a type of metal casting','jogging 指健身慢跑。'),Q('jogging',2,1,'Why does Mina go jogging?','to build endurance through regular gentle running','to sit still beside the river','to buy a jewelry installment','慢跑有助增强耐力。'),Q('jogging',3,1,'Which activity is jogging?','a relaxed run around a park','a sprinting race at maximum speed only','a walk through a museum with no running','轻松跑步属于 jogging。'),Q('jogging',4,1,'Jogging is related to which verb?','jog','jeer','jettison','jogging 来自 jog。')]);
P('joiner','Joiner 由 join 加表示施事者的 -er 构成，传统上指在工场把木料接合成门、窗、楼梯等构件的细木工。',C('joiner.s1','木工与装修','The joiner measured the oak panels twice before fitting them into the new kitchen cabinets.','细木工在把橡木板装进新厨房橱柜前量了两遍。','The joiner measured the oak panels twice / before fitting them / into the new kitchen cabinets.','joiner 指制作或安装木构件的熟练木工；before 引出安装前的准备。','量板、拼装橱柜符合细木工的工作。'),M('The joiner fitted the oak panels without measuring or joining any wooden parts.','The joiner measured and fitted the oak panels into the cabinets.','只测量但完全不制作或安装木构件，不符合此处职业义。','context'),[Q('joiner',1,1,'A joiner commonly makes or fits?','wooden doors, stairs, or cabinets','news reports for a newspaper','steel engine parts by casting','细木工制作和安装木制构件。'),Q('joiner',2,1,'Why did the joiner measure the panels?','to fit them accurately into cabinets','to report a local election','to flavour a drink with berries','测量是为准确安装橱柜。'),Q('joiner',3,1,'Which worker is most likely a joiner?','a craftsperson fitting a wooden staircase','a journalist interviewing a mayor','a judicious judge hearing a case','安装木楼梯的木工属于 joiner。'),Q('joiner',4,1,'The suffix -er in joiner marks?','a person who performs an activity','a small amount of something','a state of being joyful','-er 在此表示从事接合木工的人。')]);
P('joinery','Joinery 由 joiner 派生，指细木工的制作工艺，也可统称门、楼梯、橱柜等木制构件。',C('joinery.s1','建筑与木作','The house retained its original joinery, including panelled doors and a hand-built staircase.','这栋房子保留着原有的细木作，包括镶板门和手工制作的楼梯。','The house retained its original joinery / including panelled doors / and a hand-built staircase.','joinery 作不可数名词，指细木工艺或木构件总称；including 引出具体例子。','木门和楼梯都是房屋细木作的实例。'),M('The cottage’s joinery consisted entirely of loose vegetables and no wooden fittings.','The cottage’s joinery consisted of its wooden doors, cabinets, and staircase.','joinery 指木工构件或制作工艺，不是蔬菜。'),[Q('joinery',1,1,'Joinery is the craft or products of?','a joiner working with wood','a journalist writing a report','a judo athlete practising throws','joinery 指细木工及其木制品。'),Q('joinery',2,1,'Which item is an example of joinery?','a fitted wooden staircase','a bowl of juicy oranges','a court’s judicial authority','楼梯是常见木制构件。'),Q('joinery',3,1,'In “the house retained its original joinery,” joinery refers to?','wooden fittings such as doors and stairs','the house’s religious traditions','a group of people joining a club','句中指房屋保留的木制装饰和构件。'),Q('joinery',4,1,'Joinery is normally used as?','an uncountable noun for woodwork or wooden fittings','a plural noun for journalists','a verb meaning to juggle objects','joinery 通常作不可数名词。')]);
P('jokingly','Jokingly 由 joking 加副词后缀 -ly 构成，表示以玩笑口吻说或做，并非认真表达。',C('jokingly.s1','日常交谈','Mara jokingly asked whether the office plant deserved its own chair after it was moved beside the conference table.','办公室的植物被移到会议桌旁后，玛拉开玩笑地问它是不是也该有把椅子。','Mara jokingly asked / whether the office plant deserved its own chair / after it was moved beside the conference table.','jokingly 修饰 asked，说明提问是玩笑口吻；whether 引出问题内容。','给植物安排座位是玩笑，并非真实请求。'),M('He jokingly threatened his colleague and then insisted the threat was a formal order meant literally.','He jokingly teased his colleague, making clear that he did not mean the remark seriously.','若明确把话当正式命令且按字面认真表达，就不属于 jokingly。','word-choice'),[Q('jokingly',1,1,'If someone speaks jokingly, they speak?','as a joke rather than seriously','in a legally binding order','without using any words','jokingly 表示以玩笑方式说话。'),Q('jokingly',2,1,'Why did Mara ask about a chair for the plant?','she was making a playful joke','the plant had requested one in writing','the office had no conference table','这个问题显然是在开玩笑。'),Q('jokingly',3,1,'Which sentence uses jokingly naturally?','He jokingly called the tiny cake a banquet.','She jokingly signed a contract she intended to obey exactly.','They jokingly measured the room with a ruler silently.','把小蛋糕称作宴席是夸张玩笑。'),Q('jokingly',4,1,'Jokingly is an adverb related to which adjective?','joking','junctural','juiceless','jokingly 由 joking 派生。')]);
P('jolting','Jolting 是 jolt 加 -ing 构成的名词，指突然或反复的猛烈摇晃、颠簸。',C('jolting.s1','交通与乘坐体验','The jolting of the old bus loosened a shelf bracket and made the passengers hold on to the rails.','旧公交车的颠簸使一只搁板托架松动，乘客们只好抓紧扶手。','The jolting of the old bus loosened a shelf bracket / and made the passengers / hold on to the rails.','jolting 作名词，of the old bus 指颠簸来源；make 后接宾语加不带 to 的动词。','剧烈摇晃让乘客抓牢并震松部件。'),M('The jolting of the bus kept every passenger perfectly motionless and prevented any shaking.','The smooth ride of the bus kept the passengers from being jolted.','完全平稳、没有摇晃与 jolting 的含义相反。'),[Q('jolting',1,1,'Jolting is a?','sudden rough shaking or a series of such shakes','gentle and perfectly smooth motion','formal judgment by a court','jolting 指突然或连续的颠簸。'),Q('jolting',2,1,'What made the passengers hold the rails?','the bus’s rough jolting','a jovial conversation','a quiet walk through a garden','车身颠簸使乘客抓紧扶手。'),Q('jolting',3,1,'Which experience involves jolting?','a cart bouncing hard over a rutted road','a boat floating calmly on still water','a journalist writing at a desk','车轮在坑洼路面上剧烈弹跳属于 jolting。'),Q('jolting',4,1,'The word jolting is formed from?','jolt plus the -ing form','jewel plus -ery','joy plus -ous','jolting 是 jolt 的 -ing 形式。')]);
P('jot','Jot 的词源不确定；作动词指匆忙记下，作名词常用于 not a jot，表示丝毫或一点点。',[C('jot.s1','速记与备忘','Please jot down the gate number before the announcement ends.','请在广播结束前把登机口号码匆匆记下来。','Please jot down the gate number / before the announcement ends.','jot down 是“匆匆记下”的常见搭配；祈使句 Please 后接动词原形。','快速记录号码以免忘记，符合动词义。',''),C('jot.s2','程度与数量','The revised plan did not reduce the delay by one jot, so the team kept searching for the bottleneck.','修改后的方案丝毫没有缩短延误，因此团队继续寻找瓶颈。','The revised plan did not reduce the delay / by one jot / so the team kept searching for the bottleneck.','not one jot 是强调“丝毫没有”；by 引出变化量。','延误毫无减少，体现名词 jot 的少量义。','')],M('The revised plan shortened the delay by a jot, meaning it removed several hours from the schedule.','The revised plan shortened the delay by several hours, not merely by a jot.','a jot 表示极小数量，不能指好几个小时的大幅缩短。','word-choice'),[Q('jot',1,1,'To jot down a number is to?','write it quickly as a short note','announce it to a crowd','erase it from a screen','jot down 指快速记下。'),Q('jot',2,2,'“It did not help one jot” means it did not help?','at all, even slightly','for exactly one hour','only after a court order','not one jot 表示丝毫不。'),Q('jot',3,1,'Which is a natural use of the verb jot?','Jot down the address before you leave.','Jot the desk into a wooden chair.','Jot loudly through the crowded hall.','jot down an address 是自然搭配。'),Q('jot',4,2,'In “not a jot more,” jot means?','a very small amount','a professional woodworker','a religious tradition','名词 jot 可表示极少量。')]);
P('journalist','Journalist 由 journal 加表示职业或专长者的 -ist 构成，指采集、核实并报道新闻的从业者。',[C('journalist.s1','新闻采访','The journalist interviewed the mayor outside the flood shelter and checked the figures with two independent sources.','记者在洪灾避难点外采访了市长，并向两个独立来源核实数据。','The journalist interviewed the mayor / outside the flood shelter / and checked the figures / with two independent sources.','journalist 指采集并报道新闻的人；check ... with sources 表示核实信息。','采访并核查事实是记者的工作。'),C('journalist.s2','报刊从业','After years as a sports journalist, Mei moved from daily match reports to editing a weekly magazine.','做了多年体育记者后，梅从每日赛况报道转去编辑一份周刊。','After years as a sports journalist / Mei moved from daily match reports / to editing a weekly magazine.','sports journalist 指为报刊或媒体工作的新闻从业者；after years 表示职业经历。','长期写赛事报道并转任杂志编辑，属于新闻行业。')],M('The journalist published an unchecked rumor as fact without collecting evidence or contacting any source.','The journalist checked the rumor with several sources before reporting it as fact.','把未核实的传言直接当事实发布违背新闻核查职责。','context'),[Q('journalist',1,1,'A journalist generally collects and reports?','news','wooden fittings','religious ceremonies only','记者采集并报道新闻。'),Q('journalist',2,2,'A sports journalist might write about?','matches for a newspaper or magazine','the manufacture of a water jug','a judo belt’s material only','体育记者报道比赛。'),Q('journalist',3,1,'Why did the journalist contact independent sources?','to check whether the figures were reliable','to make the mayor jovial','to build a wooden staircase','记者通过独立来源核实数据。'),Q('journalist',4,2,'In “a journalist for a weekly magazine,” the word names?','a person working in news or publishing','a type of judicial authority','an unusually small amount','此处指新闻或出版行业从业者。')]);
P('journeyman','Journeyman 历史上与领取日薪的 journeyman 阶段相关，指完成学徒训练、仍受雇工作的熟练工；也可指水平合格但不突出的人或表现。',[C('journeyman.s1','技艺与职业阶段','After completing his apprenticeship, the journeyman printer worked for a master shop while saving to open his own business.','完成学徒训练后，这名熟练印刷工受雇于师傅的店铺，同时攒钱准备自己开业。','After completing his apprenticeship / the journeyman printer worked for a master shop / while saving to open his own business.','journeyman 指已完成学徒训练、尚未成为独立师傅的熟练工；while 表示同时进行。','他已满师但仍受雇，符合传统职业阶段义。','')],M('The journeyman printer was still an untrained beginner who had never completed an apprenticeship.','The journeyman printer had finished his apprenticeship and worked as a trained employee.','journeyman 不是未受训的初学者。','word-choice'),[Q('journeyman',1,1,'A traditional journeyman has?','finished an apprenticeship and works as a trained employee','never learned the trade','already become the only master of every shop','journeyman 通常指完成学徒期的熟练受雇工。'),Q('journeyman',2,1,'What was the printer doing after his apprenticeship?','working for a master shop','beginning training with no skills','reporting sports results as a journalist','他满师后在师傅店里工作。'),Q('journeyman',3,1,'Which person best fits the traditional meaning?','a qualified craft worker employed by another','a tourist walking on a long journey','a customer ordering a wooden desk','传统义是受雇的熟练工匠。'),Q('journeyman',4,1,'The spelling journeyman should not be read simply as?','a man who is travelling on a journey','a trained craft worker','a worker who has completed an apprenticeship','词义已专业化，不是字面“旅行的人”。')]);
P('jovial','Jovial 经中古法语来自拉丁语 jovialis“属于朱庇特”，占星传统把木星与开朗好运联系起来，今指爽朗友善、爱笑的。',C('jovial.s1','社交与气氛','Even after a long shift, the jovial baker greeted the late customers with a warm laugh and fresh rolls.','即使忙完长班，这位爽朗的面包师仍带着温暖笑声招呼晚来的顾客，并递上新鲜面包卷。','Even after a long shift / the jovial baker greeted the late customers / with a warm laugh and fresh rolls.','jovial 修饰 baker，表现亲切爽朗的性格；even after 强调忙碌后的状态。','他热情欢笑地接待顾客，体现 jovial。'),M('The jovial host was hostile and silent, refusing to greet or speak to any guest.','The jovial host welcomed the guests with friendly conversation and laughter.','冷漠、敌意且沉默与 jovial 的开朗友善相反。'),[Q('jovial',1,1,'A jovial person is usually?','cheerful and warmly friendly','hostile and unwilling to speak','careful to judge a legal case','jovial 指爽朗友善。'),Q('jovial',2,1,'What made the baker seem jovial?','he greeted customers warmly and laughed','he ignored every customer','he measured the rolls in silence','热情招呼和笑声表现开朗。'),Q('jovial',3,1,'Which atmosphere is jovial?','a friendly dinner with laughter and easy conversation','a tense hearing where no one speaks','a jolting bus ride in heavy rain','轻松欢笑的晚餐气氛是 jovial。'),Q('jovial',4,1,'Jovial is closest to?','good-humoured','inaccessible','jolting','jovial 与 good-humoured 相近。')]);
P('joyous','Joyous 由 joy 加 -ous 构成，形容充满喜悦的体验，也可形容能带给别人欢乐的消息或场合。',[C('joyous.s1','庆祝与情绪','The team shared a joyous embrace after the final whistle confirmed their first championship.','终场哨确认他们首次夺冠后，队员们喜悦地拥抱在一起。','The team shared a joyous embrace / after the final whistle confirmed / their first championship.','joyous 修饰 embrace，描述充满喜悦的动作；after 引出喜悦的原因。','首次夺冠引发强烈欢乐，符合 s1。'),C('joyous.s2','令人愉快的消息','The hospital sent joyous news to the family when the child was cleared to return home.','孩子获准回家时，医院把令人欣喜的消息告诉了家人。','The hospital sent joyous news to the family / when the child was cleared / to return home.','joyous 修饰 news，表示消息本身能带来欢乐，对应“令人高兴的”义。','康复出院的消息让家人高兴。')],M('The team described the championship as joyous, although every player felt miserable and no one celebrated.','The team celebrated the championship in a joyous mood, embracing after the final whistle.','无人庆祝且情绪痛苦，与充满喜悦相矛盾。'),[Q('joyous',1,1,'A joyous celebration is?','full of happiness','marked by anger and grief only','a court’s authority','joyous 表示充满喜悦。'),Q('joyous',2,2,'“The joyous news” means the news?','causes happiness in those who hear it','is impossible to understand','was written by a woodworker','s2 是令人高兴的消息。'),Q('joyous',3,1,'Why was the team joyous?','it had just won its first championship','it lost the final and refused to play','the bus ride was smooth','首次夺冠是队员喜悦的原因。'),Q('joyous',4,2,'Which phrase uses the “causing joy” sense?','joyous news of a safe return','a joyous crowd celebrating','a jovial baker laughing','joyous news 表示带来喜悦的消息。')]);
P('jubilant','Jubilant 由拉丁语 jubilare“欢呼”相关词演变而来，形容因成功或好消息而欢欣鼓舞、带有胜利感。',C('jubilant.s1','比赛与庆功','Jubilant supporters waved scarves through the city streets after their club won the cup on penalties.','球队点球夺冠后，欢腾的支持者挥舞围巾走过城市街道。','Jubilant supporters waved scarves / through the city streets / after their club won the cup on penalties.','jubilant 修饰 supporters，突出因获胜而欢欣鼓舞；after 引出喜悦原因。','点球夺冠后庆祝体现带有胜利感的喜悦。'),M('The jubilant supporters mourned the victory in silence and refused to celebrate it.','The jubilant supporters celebrated the victory with cheers and waving scarves.','哀悼并拒绝庆祝与 jubilant 的欢腾状态相反。'),[Q('jubilant',1,1,'Jubilant people are?','extremely happy, often because of a success','quietly doubtful about every outcome','angry at an unfair decision','jubilant 指因成功而欢欣鼓舞。'),Q('jubilant',2,1,'Why were the supporters jubilant?','their club had won the cup','their team had lost the final','they were attending a woodworking class','球队夺冠令支持者欢腾。'),Q('jubilant',3,1,'Which scene is jubilant?','a crowd cheering after a surprise victory','a silent crowd mourning a defeat','a journalist checking an ordinary timetable','胜利后欢呼的人群是 jubilant。'),Q('jubilant',4,1,'Jubilant most strongly suggests?','triumphant joy','mild politeness','careful judgment','jubilant 常带有胜利的喜悦。')]);
P('Judaism','Judaism 经希腊语 Ioudaismos 和拉丁语进入英语，词根与 Judah/Jewish 相关，指犹太民族的宗教，也可广义指其传统文化与生活方式。',[C('Judaism.s1','宗教与经典','The museum’s guide explained how the Torah shapes worship and religious study within Judaism.','博物馆讲解员介绍了《托拉》如何影响犹太教中的礼拜和宗教学习。','The museum’s guide explained / how the Torah shapes worship and religious study / within Judaism.','Judaism 作专有宗教名称，首字母大写；how 引出讲解内容。','礼拜与《托拉》学习体现犹太教的宗教传统。'),C('Judaism.s2','文化与传统','The exhibition explored the music, food, and family customs associated with Judaism across several communities.','展览呈现了多个社群中与犹太传统相关的音乐、饮食和家庭习俗。','The exhibition explored the music, food, and family customs / associated with Judaism / across several communities.','此处 Judaism 指相关文化与生活传统；associated with 限定习俗关联。','音乐、饮食和家庭习俗属于广义文化生活。')],M('The article used Judaism as an adjective for a single Jewish person rather than naming a religion or tradition.','The article described Judaism as a religion and discussed the traditions associated with it.','Judaism 是宗教或传统总称，个人身份应使用 Jewish person 或 Jew，避免混淆。','word-formation'),[Q('Judaism',1,1,'Judaism is primarily the religion of?','the Jewish people','the ancient Romans only','people who practise judo','Judaism 是犹太民族的宗教。'),Q('Judaism',2,2,'A museum display about food and customs of Judaism focuses on?','cultural traditions associated with Jewish communities','a single court’s legal authority','the rules of Japanese martial arts','此处指犹太社群的文化传统。'),Q('Judaism',3,1,'Which spelling is the religion’s name?','Judaism','Judaismic','Judaismer','Judaism 是宗教名称的标准拼写。'),Q('Judaism',4,1,'In “Judaism is a major world religion,” the word names?','a religion','an individual follower','a language spoken only in Japan','句中 Judaism 是宗教名。')]);
P('judicature','Judicature 经法语源自中世纪拉丁语 judicatura，与 judicium“审判”相关，指司法制度或行使司法的权力。',C('judicature.s1','宪政与司法','The new charter defines the limits of the judicature and protects the courts from political interference.','新宪章规定了司法权的界限，并保护法院免受政治干预。','The new charter defines the limits of the judicature / and protects the courts / from political interference.','judicature 指由法院实施的司法权或司法体系；limits of 标出其权限边界。','宪章规定法院职权边界，体现司法制度和权力义。'),M('The constitution assigned all judicature to the legislature and described the courts as having no judicial function.','The constitution separated the judicature from the legislature and gave the courts judicial authority.','judicature 是法院行使的司法权，与立法机构职能相区分。','meaning'),[Q('judicature',1,1,'Judicature refers to?','the administration of justice or judicial authority','the writing of newspaper columns','the craft of fitting wooden doors','judicature 指司法或审判权。'),Q('judicature',2,1,'What did the charter protect from political interference?','the courts and their judicial work','the local joiner’s workshop','the judo team’s training hall','宪章保护法院及其司法工作。'),Q('judicature',3,1,'Judicature is more abstract than the word for?','a particular courthouse building','the legal authority exercised by courts','the judicial system as a whole','judicature 指制度或权力，不特指一栋建筑。'),Q('judicature',4,1,'Which branch is usually contrasted with the judicature?','the legislature','a group of jovial supporters','a trade in juicy fruit','司法权常与立法权相区分。')]);
P('judicious','Judicious 由拉丁语 judicium“判断”相关词加形容词后缀 -ous 构成，表示判断明智、审慎周全。',[C('judicious.s1','决策与资源','The council made a judicious choice to repair the bridge in stages, keeping one lane open for emergency vehicles.','委员会明智地决定分阶段维修桥梁，同时为应急车辆保留一条车道。','The council made a judicious choice / to repair the bridge in stages / keeping one lane open for emergency vehicles.','judicious 修饰 choice，表示经过审慎判断的选择；to repair 说明选择内容。','兼顾施工与应急通行，体现周全判断。'),C('judicious.s2','人物判断','A judicious editor questioned the anonymous claim and asked for evidence before publishing it.','一位审慎精明的编辑质疑了匿名说法，并在发表前要求提供证据。','A judicious editor questioned the anonymous claim / and asked for evidence / before publishing it.','judicious 修饰 editor，表示此人判断谨慎；before 引出发表前的核查。','要求证据再刊发显示谨慎判断。')],M('The judicious editor published the anonymous claim immediately without checking whether it was supported by evidence.','The judicious editor checked the anonymous claim and its evidence before publishing it.','不核实便发布匿名说法与审慎判断相冲突。','context'),[Q('judicious',1,1,'A judicious decision is made with?','good judgment and care','no thought about likely results','a desire to make people laugh','judicious 表示明智审慎。'),Q('judicious',2,2,'Why is the editor judicious?','she asks for evidence before publishing an anonymous claim','she publishes every rumor instantly','she ignores all available records','发表前索要证据体现审慎判断。'),Q('judicious',3,1,'Which choice is judicious?','repairing a bridge in stages while keeping emergency access','closing every route without considering emergencies','spending a budget before reviewing any costs','兼顾维修和应急通行是周全安排。'),Q('judicious',4,2,'Judicious is closest in meaning to?','prudent','jubilant','jolting','judicious 与 prudent 都表示审慎明智。')]);
P('judo','Judo 是日语柔道术语，由 ju“柔、温和”与 dō“道、方法”构成，指以摔投、压制和控制为主的日本武术。',C('judo.s1','武术训练','In judo class, beginners practise balance and safe falling before learning to throw a partner.','柔道课上，初学者先练平衡和安全倒地，再学习摔投同伴。','In judo class / beginners practise balance and safe falling / before learning to throw a partner.','judo 是武术项目名，通常作不可数名词；before learning 表示训练先后。','先练平衡和安全倒地，再学摔技，符合柔道训练。'),M('The judo match was won by striking the opponent repeatedly with punches, the sport’s central technique.','The judo match was won with a controlled throw and pin rather than repeated punches.','柔道以摔投和控制为主，不以反复拳击为核心。','meaning'),[Q('judo',1,1,'Judo is a Japanese martial art that emphasizes?','throws, balance, and control','woodworking joints and fittings','striking with punches as its only technique','柔道以摔投、平衡和控制为主。'),Q('judo',2,1,'What do beginners practise before throwing a partner?','balance and safe falling','publishing a weekly report','jotting down legal orders','柔道初学者先练平衡和安全倒地。'),Q('judo',3,1,'Which skill belongs to judo?','using a controlled throw to take an opponent down','serving a ball over a net','judging a court appeal','控制摔投属于柔道技能。'),Q('judo',4,1,'Judo is normally treated as?','an uncountable name of a sport or martial art','a countable word for one written note','the plural form of judge','judo 通常作为不可数运动名称。')]);
P('jug','Jug 的词源不确定；作名词指有柄、有嘴、用于盛液体的深容器，作动词也可指在有盖锅中慢炖肉类。',[C('jug.s1','厨房与盛水','She poured the lemonade from a glass jug into small cups beside the picnic basket.','她把玻璃壶里的柠檬水倒进野餐篮旁的小杯子。','She poured the lemonade / from a glass jug / into small cups beside the picnic basket.','jug 作名词指带柄、便于倒液体的容器；from 和 into 标明倒出与倒入。','玻璃壶盛装并倒出饮料，符合容器义。'),C('jug.s2','烹饪方法','The recipe asks the cook to jug the hare slowly in a covered pot until the meat is tender.','食谱要求把野兔放在有盖锅里慢慢炖，直到肉变软。','The recipe asks the cook / to jug the hare slowly in a covered pot / until the meat is tender.','jug 作动词表示在有盖容器中慢炖；to jug 后接被炖的肉类。','有盖锅里慢慢烹煮至软烂，体现烹饪义。')],M('The cook jugged the hare by serving it raw from an uncovered plate without heating it.','The cook jugged the hare slowly in a covered pot until it was tender.','生食且不加热并非把肉放在有盖锅中慢炖。','word-choice'),[Q('jug',1,1,'A glass jug is a container usually used for?','holding and pouring liquids','writing down a quick note','throwing an opponent in judo','jug 常用来盛装和倒出液体。'),Q('jug',2,2,'To jug meat in cooking is to?','stew it slowly in a covered pot','serve it raw on an open plate','fry it quickly without a pot','jug 作烹饪动词指有盖慢炖。'),Q('jug',3,1,'Which object best fits the noun jug?','a handled vessel with a spout for lemonade','a small paper slip with a reminder','a wooden joint fitted by a joiner','带柄并能倒饮料的容器是 jug。'),Q('jug',4,2,'In “jug the hare until tender,” jug is?','a cooking verb','a name for a reporter','an adjective meaning joyful','句中 jug 是慢炖的动词。')]);
P('juggle','Juggle 经古法语及拉丁语 joculari“开玩笑、戏耍”相关词演变，作动词指抛接物品或同时处理多项事务，作名词也可指把事实拼凑起来的手法。',[C('juggle.s1','时间与任务','During the busy term, Nia juggled a laboratory placement with evening classes and weekend care for her grandfather.','学期繁忙时，妮娅一边做实验室实习，一边上夜课，还要周末照料祖父。','During the busy term / Nia juggled a laboratory placement with evening classes / and weekend care for her grandfather.','juggle 作动词引申为同时应付多项任务；juggle A with B 表示兼顾。','她同时承担实习、课程和照料责任。'),C('juggle.s2','事实与解释','The auditor called the report a juggle of figures because it moved costs between categories to hide the shortfall.','审计员称这份报告是在拼凑数字，因为它把成本在不同类别间挪动以掩盖亏空。','The auditor called the report a juggle of figures / because it moved costs between categories / to hide the shortfall.','juggle 作名词，a juggle of figures 指对数字的巧妙摆弄；because 说明原因。','挪动数据类别掩盖亏空体现名词的拼凑操弄义。')],M('The auditor praised the report as an honest juggle of figures even though it deliberately shifted costs to conceal a loss.','The auditor criticized the report as a deceptive juggle of figures that concealed a loss.','故意转移成本掩盖亏空属于操弄数字，不应称为诚实透明的处理。','meaning'),[Q('juggle',1,1,'To juggle work and study is to?','manage both at the same time','give up both responsibilities','turn the work into a wooden fitting','juggle 可指同时应付多项事务。'),Q('juggle',2,2,'A “juggle of figures” may be?','a questionable rearrangement of numbers','a clear and unchanged audit record','a sport using only a ball and a net','名词义可指对数字的拼凑摆弄。'),Q('juggle',3,1,'Which person is juggling responsibilities?','a student who works part-time and attends classes','a person who has only one short task','a reporter writing about a finished event','同时兼顾工作和课程属于 juggle。'),Q('juggle',4,1,'Juggle originally can describe?','throwing and catching several objects','stewing meat in a closed pot','issuing a judicial ruling','杂耍抛接物品是 juggle 的常见具体义。')]);
P('juicy','Juicy 由 juice 加形容词后缀 -y 构成，可指含汁多、口感鲜嫩，也可非正式地指细节丰富、令人兴奋甚至带点丑闻色彩的故事。',[C('juicy.s1','水果与口感','The peaches stayed juicy because the grocer stored them away from the hot display window.','这些桃子仍然汁水丰盈，因为杂货商把它们放在远离炎热橱窗的地方。','The peaches stayed juicy / because the grocer stored them / away from the hot display window.','juicy 描述桃子汁液充足、口感多汁；because 引出保存方式。','避开高温有助保持水果水分。'),C('juicy.s2','新闻与闲谈','The magazine promised a juicy account of the rivalry, including private letters and details neither singer had shared before.','杂志承诺刊出一篇关于这场竞争的劲爆报道，其中包括双方歌手从未公开的私人信件和细节。','The magazine promised a juicy account of the rivalry / including private letters / and details neither singer had shared before.','juicy 修饰 account，非正式地表示故事细节丰富且引人关注。','报道含私人信件和新细节，体现绘声绘色、劲爆的引申义。')],M('The juicy peaches contained no moisture and were completely dry inside.','The juicy peaches were full of moisture and sweet when ripe.','完全干燥的桃子与 juicy 的多汁义相反。'),[Q('juicy',1,1,'A juicy peach is?','full of juice and moisture','dry and hard throughout','a type of court document','juicy 可指水果汁水充足。'),Q('juicy',2,2,'A juicy story usually has?','interesting and possibly shocking details','no details that would interest anyone','a recipe for stewing meat','juicy story 指内容丰富、引人关注的故事。'),Q('juicy',3,1,'Why were the peaches juicy?','they had retained their moisture','they were left to dry in direct heat','they were turned into a glass container','桃子保留水分所以多汁。'),Q('juicy',4,2,'Which collocation fits the figurative sense?','juicy gossip about the rivalry','juicy judicature of a court','juicy judo throw','juicy gossip 表示劲爆闲谈。')]);
P('jumble','Jumble 的词源不确定；作动词指把不同东西混杂得凌乱，作名词指各式物品混在一起的杂乱一堆。',[C('jumble.s1','整理与分类','Please do not jumble the signed forms with blank copies; the clerk needs to file them separately.','请不要把签过字的表格和空白副本混在一起；办事员需要分开归档。','Please do not jumble the signed forms with blank copies / the clerk needs to file them separately.','jumble A with B 表示把两类东西混在一起；do not 后接动词原形。','签字件与空白件若混放会妨碍归档。',''),C('jumble.s2','杂物与物品堆','A jumble of cables and old adapters filled the bottom drawer, so no one could find the charger.','抽屉底部塞满了乱成一团的电缆和旧转接头，谁也找不到充电器。','A jumble of cables and old adapters / filled the bottom drawer / so no one could find the charger.','a jumble of 是“杂乱的一堆”；of 后接混杂物品。','各种线缆和转接头杂乱堆在一起，符合名词义。')],M('The clerk carefully separated every signed form and blank copy, so the papers were not jumbled together.','The clerk accidentally jumbled the signed forms together with the blank copies.','有序分开放置不是 jumble；将它们混放才是。','word-choice'),[Q('jumble',1,1,'To jumble papers is to?','mix them together in a confused way','sort them into clearly labeled folders','write a short note on each one','jumble 作动词指把东西弄混乱。'),Q('jumble',2,2,'A jumble of cables is?','a confused mass of cables','a single neatly coiled cable','a report written by a journalist','名词 jumble 指乱成一堆的东西。'),Q('jumble',3,1,'What happened to the forms when they were jumbled?','signed and blank copies became mixed','each form was filed in its own folder','all forms were converted into a jug','表格混在一起就是被 jumbled。'),Q('jumble',4,2,'Which phrase uses jumble as a noun?','a jumble of old adapters','to jumble the labels','they jumble the files','a jumble of 是名词用法。')]);
P('juncture','Juncture 源自拉丁语 iunctura“连接、接合”，经法语进入英语；既可指两物连接处，也常指关键时刻或重要关头。',[C('juncture.s1','关键时刻','At this juncture, the negotiators had to decide whether to extend the ceasefire or return to the talks next month.','在这个关键时刻，谈判代表必须决定是延长停火，还是下个月再恢复会谈。','At this juncture / the negotiators had to decide / whether to extend the ceasefire / or return to the talks next month.','at this juncture 是正式表达，意为“在这个关头”；whether...or 提供两种选择。','谈判即将作出重要决策，体现关键时刻义。'),C('juncture.s2','连接与交汇','The engineer inspected the juncture where the new pipe met the older concrete channel.','工程师检查了新管道与旧混凝土水渠相接的位置。','The engineer inspected the juncture / where the new pipe met / the older concrete channel.','juncture 指两物相接的地方；where 引导位置从句。','管道与水渠的交汇处是两物连接点。')],M('At this juncture, the decision had already been made years earlier and no one faced an important choice.','At this juncture, the committee faced a consequential choice about the project’s future.','若没有当前重要决策，就不能称为关键关头。','context'),[Q('juncture',1,1,'At this juncture means?','at this important point in time','inside a glass jug','during a judo practice only','at this juncture 表示在这一关键时刻。'),Q('juncture',2,2,'The juncture of two pipes is?','the place where they meet','a long section where neither connects','the pipe’s printed instruction sheet','接合处是两根管道相遇的位置。'),Q('juncture',3,1,'Why was the meeting at a juncture?','the negotiators faced an important decision','the meeting had no decisions or consequences','the pipes were being measured in a workshop','面临重要决定使会谈处于关键关头。'),Q('juncture',4,2,'Which sentence uses the physical sense of juncture?','A crack formed at the juncture of the two panels.','At this juncture, the council must vote.','The reporter jotted down a quote.','两块板的接缝处体现物理接合义。')]);
P('juniper','Juniper 经古法语源自拉丁语 juniperus，指一种常绿针叶灌木或小乔木，其芳香浆果常用于给金酒调味。',C('juniper.s1','植物与香料','The distiller added dried juniper berries to the spirit, giving the gin its characteristic pine-like aroma.','蒸馏师把干杜松子加入酒中，使金酒带有标志性的松木般香气。','The distiller added dried juniper berries to the spirit / giving the gin / its characteristic pine-like aroma.','juniper berries 指杜松子的浆果；giving 补充加料后产生的香气效果。','杜松子是金酒传统香味来源之一。'),M('The distiller used juniper berries because they have no aroma and are never used to flavour gin.','The distiller used aromatic juniper berries to flavour the gin.','杜松子有芳香且常用于金酒调味，因此“无香、不用于调味”错误。','meaning'),[Q('juniper',1,1,'A juniper is an evergreen?','shrub or small tree with aromatic berries','deciduous flower with no woody stem','large bird that feeds on acorns','juniper 是常绿灌木或小树。'),Q('juniper',2,1,'What do juniper berries traditionally flavour?','gin','judo uniforms','wooden joinery','杜松子常用于给金酒调味。'),Q('juniper',3,1,'What aroma may juniper berries add?','a sharp, pine-like scent','a scentless quality by removing all oils','the smell of fresh paper only','杜松子具有辛香、近似松木的气味。'),Q('juniper',4,1,'Juniper belongs to which kind of plant?','an evergreen coniferous shrub or small tree','a soft-bodied sea animal','a climbing flowering vine only','刺柏属于常绿针叶植物。')]);
P('Jupiter','Jupiter 经拉丁语 Iuppiter 进入英语，既是太阳系最大行星的名称，也是罗马神话中的主神朱庇特。',[C('Jupiter.s1','天文学','Jupiter’s four large moons were visible through the observatory telescope on a clear winter night.','晴朗的冬夜里，人们透过天文台的望远镜看到了木星的四颗大型卫星。','Jupiter’s four large moons were visible / through the observatory telescope / on a clear winter night.','Jupiter 指行星时首字母大写；moons 是行星的卫星。','望远镜观察到的四颗大卫星围绕木星运行。'),C('Jupiter.s2','罗马神话','The Roman temple was dedicated to Jupiter, whom the inscription praised as king of the gods.','这座罗马神庙供奉朱庇特，碑文称颂他为众神之王。','The Roman temple was dedicated to Jupiter / whom the inscription praised / as king of the gods.','Jupiter 指罗马神话中的主神；whom 指被供奉的神祇。','“众神之王”的称号对应罗马神话中的朱庇特。')],M('The astronomer called Jupiter the smallest planet in the solar system because it is smaller than every asteroid.','The astronomer described Jupiter as the largest planet in the solar system.','木星是太阳系最大的行星，不是最小的行星。','meaning'),[Q('Jupiter',1,1,'In astronomy, Jupiter is?','the largest planet in the solar system','a moon orbiting Earth','the smallest asteroid in the belt','Jupiter 是太阳系最大的行星。'),Q('Jupiter',2,2,'In Roman mythology, Jupiter was?','king of the gods','the Greek name for Mars only','a famous Roman shipbuilder','罗马神话中的朱庇特是众神之王。'),Q('Jupiter',3,1,'What did the telescope reveal in the example?','four of Jupiter’s large moons','a new wooden keel','a court’s judicature','例句写望远镜观察木星的卫星。'),Q('Jupiter',4,2,'A temple dedicated to Jupiter would honor?','the Roman chief god','a New Zealand parrot','the Greek goddess of the harvest','供奉 Jupiter 的罗马神庙是在敬奉主神。')]);
P('justly','Justly 由形容词 just 加副词后缀 -ly 构成，表示公平地，或有充分理由地、名副其实地。',C('justly.s1','奖项与公平','The panel justly awarded the scholarship to Ana after comparing every applicant’s work against the same criteria.','评审小组按同一标准比较所有申请者的作品后，公正地把奖学金授予安娜。','The panel justly awarded the scholarship to Ana / after comparing every applicant’s work / against the same criteria.','justly 修饰 awarded，表示颁发过程公平；after 引出评审依据。','所有人使用相同标准，体现公正授奖。'),M('The panel justly chose Ana only because she was related to a judge and ignored every applicant’s work.','The panel fairly chose Ana after assessing all applicants by the same criteria.','因亲属关系偏袒而无视作品不属于公正评选。','meaning'),[Q('justly',1,1,'To distribute a prize justly is to do so?','fairly','without looking at the candidates','for no reason at all','justly 表示公平地或有正当理由地。'),Q('justly',2,1,'Why was Ana justly awarded the scholarship?','the panel used the same criteria for every applicant','the panel ignored all applications','she had purchased the judges’ votes','一致的评选标准支持公正结果。'),Q('justly',3,1,'In “justly famous,” justly most nearly means?','deservedly','a moment ago','only and no more','justly famous 是名副其实地有名。'),Q('justly',4,1,'Justly is formed from?','just plus -ly','jot plus -ly','judo plus -ly','justly 由 just 加 -ly 构成。')]);
P('juxtapose','Juxtapose 由拉丁语 juxta“旁边”与法语 poser“放置”相关成分组成，指把两物并排放置以呈现差异或联系。',C('juxtapose.s1','艺术与对比','The photographer juxtaposed a crowded market with an empty playground to show how the neighborhood changed after dark.','摄影师把拥挤的市场与空荡的操场并置，展示这个街区入夜后的变化。','The photographer juxtaposed a crowded market with an empty playground / to show / how the neighborhood changed after dark.','juxtapose A with B 是把甲乙并置对照；to show 说明并置目的。','两个场景并排呈现以凸显昼夜变化。'),M('The exhibition juxtaposed the two paintings by hiding one in storage where visitors could never see it.','The exhibition juxtaposed the two paintings side by side so visitors could compare them.','把作品藏起来而不同时展示，不是并置。','word-choice'),[Q('juxtapose',1,1,'To juxtapose two images is to?','place them side by side for comparison','erase both images permanently','measure the weight of each image','juxtapose 指并排放置以比较。'),Q('juxtapose',2,1,'Why did the photographer juxtapose a market and a playground?','to highlight a contrast in the neighborhood','to show that both places were identical','to conceal one of the photographs','并置两种场景能突出差异。'),Q('juxtapose',3,1,'Which construction is natural?','juxtapose the old design with the new one','juxtapose the old design from the new one','juxtapose that the old design to the new one','常用结构是 juxtapose A with B。'),Q('juxtapose',4,1,'Juxtapose is a verb meaning?','put things next to one another','treat meat in a covered pot','fall over from heat','juxtapose 意为并置。')]);
P('juxtaposition','Juxtaposition 由 juxtapose 加名词后缀 -ition 构成，指把事物放在相邻位置，常借此形成对照效果。',C('juxtaposition.s1','设计与构图','The juxtaposition of rough stone and polished steel gives the entrance hall a striking modern feel.','粗粝石材与抛光钢材的并置，让入口大厅呈现鲜明的现代感。','The juxtaposition of rough stone and polished steel / gives the entrance hall / a striking modern feel.','juxtaposition of A and B 表示甲乙并置；谓语 gives 指并置带来的效果。','质感相反的材料并排使用，形成明显对照。'),M('The designer called it a juxtaposition, although the stone and steel were stored in separate buildings and never shown together.','The designer created a juxtaposition by placing the stone and steel together in the same hall.','两件物品不相邻展示，不能称为此处的并置。'),[Q('juxtaposition',1,1,'A juxtaposition is?','the placement of things close together, often for contrast','the removal of one item from a display','a repeated press of a keyboard key','juxtaposition 指并置，常用来突出差异。'),Q('juxtaposition',2,1,'What contrast appears in the hall?','rough stone beside polished steel','two identical polished steel panels only','a hidden stone in another building','粗石和抛光钢材形成材质对照。'),Q('juxtaposition',3,1,'Which phrase is correct?','the juxtaposition of old and new','the juxtaposition to old from new','the juxtaposition under old into new','常见搭配是 the juxtaposition of。'),Q('juxtaposition',4,1,'Juxtaposition is the noun related to which verb?','juxtapose','jubilate','jot','juxtaposition 对应动词 juxtapose。')]);
P('kangaroo','Kangaroo 借自澳大利亚昆士兰地区的 Guugu Yimithirr 语 gangurru，指后腿强健、以跳跃移动并有育儿袋的澳洲有袋动物。',C('kangaroo.s1','野生动物','A kangaroo carried its joey in a pouch while crossing the dry grassland at sunrise.','一只袋鼠在日出时穿过干燥草地，育儿袋里带着幼崽。','A kangaroo carried its joey in a pouch / while crossing the dry grassland / at sunrise.','kangaroo 指袋鼠；幼崽常称 joey，pouch 是育儿袋。','跳跃移动和育儿袋是袋鼠的典型特征。'),M('The kangaroo carried its young in a hard eggshell and flew away from the grassland.','The kangaroo carried its young in a pouch and moved by powerful jumps.','袋鼠是有袋类，不产需要硬壳孵化的蛋，也不会飞。','meaning'),[Q('kangaroo',1,1,'A kangaroo is a large Australian?','marsupial with strong hind legs and a pouch','bird that hovers over mice','brown seaweed growing underwater','袋鼠是澳大利亚有袋动物。'),Q('kangaroo',2,1,'Where does a kangaroo carry its young?','in a pouch','under its wing','inside a wooden keel','袋鼠用育儿袋携带幼崽。'),Q('kangaroo',3,1,'How does a kangaroo commonly move?','by hopping on powerful back legs','by swimming with flippers','by walking on four short legs only','袋鼠以强壮后腿跳跃移动。'),Q('kangaroo',4,1,'A young kangaroo is often called a?','joey','jot','kea','袋鼠幼崽常称 joey。')]);
P('karma','Karma 来自梵语 karman“行为、行动”，在印度宗教传统中指行为及其后果的因果原则，口语中也可戏称“报应”。',C('karma.s1','因果与责任','She described the apology as good karma after she had spent the morning helping the neighbors rebuild their fence.','她上午帮邻居重建围栏后，把这声道歉称作善有善报。','She described the apology as good karma / after she had spent the morning / helping the neighbors rebuild their fence.','karma 指行为与后果之间的因果观；此处是轻松口语用法。','先帮助邻居，后收到道歉，被说成善意行为带来的回报。'),M('He called the reward bad karma even though it was a punishment for his own harmful actions.','He called the reward good karma after his helpful actions.','奖励被称为 bad karma 与所述善行回报的语境不符。','meaning'),[Q('karma',1,1,'In religious traditions, karma concerns?','how actions influence later consequences','how a keel keeps a boat steady','how a court selects its judges','karma 与行为及其后果有关。'),Q('karma',2,1,'Why did she call the apology good karma?','she had helped her neighbors earlier','she had refused to help anyone','the fence was built from kelp','她把善意帮助与后来的好结果联系起来。'),Q('karma',3,1,'A casual remark about “bad karma” often suggests?','an unpleasant consequence seen as deserved','a type of Australian marsupial','a technique for comparing photographs','口语中 bad karma 可指自食其果。'),Q('karma',4,1,'Karma comes from which language?','Sanskrit','Old English','Guugu Yimithirr','karma 源自梵语。')]);
P('karst','Karst 得名于斯洛文尼亚的 Kras 地区，经德语 Karst 进入地质学英语，指可溶岩石被水溶蚀形成的洞穴、落水洞等地貌。',C('karst.s1','地貌与地质','Rainwater slowly widened the limestone fissures, creating a karst landscape of caves and sinkholes.','雨水逐渐扩大石灰岩裂隙，形成由洞穴和落水洞组成的喀斯特地貌。','Rainwater slowly widened the limestone fissures / creating a karst landscape / of caves and sinkholes.','karst 修饰 landscape，说明岩石经溶蚀形成的地貌类型；of 列举地形。','石灰岩裂隙溶蚀并形成洞穴和落水洞，符合喀斯特形成过程。'),M('The geologist called the flat, unweathered granite plain a karst landscape full of limestone sinkholes.','The geologist called the limestone terrain with caves and sinkholes a karst landscape.','喀斯特典型由可溶岩石如石灰岩溶蚀形成，不能把未经溶蚀的花岗岩平原说成此类地貌。','meaning'),[Q('karst',1,1,'Karst landscapes are commonly shaped by?','water dissolving limestone or other soluble rock','wind polishing pure steel into an arch','young kangaroos digging wooden tunnels','喀斯特地貌常由水溶蚀石灰岩形成。'),Q('karst',2,1,'Which feature may occur in karst?','a sinkhole formed by dissolved rock','a glacier made only of seaweed','a straight keel along a boat hull','落水洞是常见喀斯特地形。'),Q('karst',3,1,'What rock is common in karst terrain?','limestone','unweathered wood','soft wool','喀斯特多见于石灰岩地区。'),Q('karst',4,1,'Karst is a term from?','geology and landforms','journalism and publishing','martial arts and sport','karst 是地质地貌术语。')]);
P('kea','Kea 是借自毛利语的鸟名，指新西兰南岛高山地区的一种大型鹦鹉，以好奇和强有力的喙著称。',C('kea.s1','鸟类与野外观察','A kea tugged at the rubber seal on the parked car while hikers watched from a safe distance.','一只啄羊鹦鹉扯着停放汽车的橡胶密封条，徒步者则在安全距离外观看。','A kea tugged at the rubber seal / on the parked car / while hikers watched from a safe distance.','kea 指新西兰山地鹦鹉；while 表示动作同时发生。','好奇地啄扯器物符合啄羊鹦鹉的行为特点。'),M('The kea was a flightless fish with no beak that lived in a desert river.','The kea was a curious mountain parrot with a strong beak.','kea 是有喙的鸟类，不是鱼。','meaning'),[Q('kea',1,1,'A kea is a parrot native to?','the mountains of New Zealand','the Australian outback only','the cold coastal kelp forests','kea 是新西兰山地鹦鹉。'),Q('kea',2,1,'What did the kea tug at?','the car’s rubber seal','a court’s legal charter','a bottle of kerosene','例句中它扯汽车的橡胶密封条。'),Q('kea',3,1,'What trait is associated with kea?','curiosity and a strong beak','a pouch for carrying joeys','a habit of hovering over mice','kea 好奇且喙有力。'),Q('kea',4,1,'A kea belongs to which animal group?','birds','fish','marsupials','啄羊鹦鹉属于鸟类。')]);
P('keel','Keel 源自古英语 cēol 等早期航海词形，作名词指沿船底纵向延伸的主梁，也可在 keel over 中作动词表示倾覆或突然倒下。',[C('keel.s1','船体结构','The boatyard inspected the keel before repainting the hull and returning the sailboat to the water.','船厂在给船体重新刷漆并把帆船放回水里之前检查了龙骨。','The boatyard inspected the keel / before repainting the hull / and returning the sailboat to the water.','keel 作名词指船底的纵向主梁；before 表示检查先于重新下水。','检查船底主梁是船舶维护的一部分。'),C('keel.s2','突然倒下','After standing in the heat for hours, the exhausted runner keeled over beside the finish line.','在高温下站了几个小时后，筋疲力尽的跑者在终点线旁突然倒下。','After standing in the heat for hours / the exhausted runner keeled over / beside the finish line.','keel over 是不及物短语动词，表示倾覆或人突然倒下；此处为比喻性倒下。','跑者中暑般突然倒地对应动词义。')],M('The runner keeled over but remained upright and continued walking without falling.','The runner keeled over and collapsed beside the finish line.','keeled over 表示翻倒或突然倒下，不是保持站立。','meaning'),[Q('keel',1,1,'A boat’s keel is?','a long structural beam along the bottom of its hull','a small shelter where a dog sleeps','a key pressed on a keyboard','船龙骨是沿船底延伸的结构梁。'),Q('keel',2,2,'If a runner keels over, the runner?','falls or collapses suddenly','jogs gently around the track','places two pictures side by side','keel over 表示突然倒下。'),Q('keel',3,1,'Where is a keel found?','along the bottom of a boat','at the top of an arch','inside a keyboard key','龙骨位于船底。'),Q('keel',4,2,'Which phrase is used for sudden collapse?','keel over','jot down','juggle with','keel over 表示倾覆或倒下。')]);
P('keelboat','Keelboat 由 keel 与 boat 组合，指带有龙骨的船，历史上常指在美国浅水河流运输货物的内河船。',C('keelboat.s1','河运史','Before railways reached the valley, a keelboat carried flour and timber downstream to the port.','铁路通到山谷之前，一艘龙骨船把面粉和木材运往下游港口。','Before railways reached the valley / a keelboat carried flour and timber downstream / to the port.','keelboat 指带龙骨的船；downstream 表示顺流而下。','船只沿河运输货物，体现历史内河货船用途。'),M('The historian described the keelboat as a wagon with wheels used only on dry mountain roads.','The historian described the keelboat as a river vessel with a keel used to carry freight.','keelboat 是水上船只，不是陆路马车。','meaning'),[Q('keelboat',1,1,'A keelboat is?','a boat built with a keel','a dog shelter with a wooden floor','a bird that hunts while hovering','keelboat 指带龙骨的船。'),Q('keelboat',2,1,'What might a historic keelboat carry?','freight along a river','court judgments through a keyboard','judo students to a dojo on foot','历史龙骨船常用于内河货运。'),Q('keelboat',3,1,'Where does a keelboat travel?','on water, often along a river','only on dry mountain roads','through the air above a forest','keelboat 是水上交通工具。'),Q('keelboat',4,1,'The word keelboat is formed from?','keel plus boat','kea plus boat','ken plus boat','keelboat 由 keel 和 boat 组成。')]);
P('kelp','Kelp 作为海藻名称的词源不确定，通常指寒冷海域生长的大型褐藻，可形成海底森林并提供栖息地。',C('kelp.s1','海洋生态','Sea otters searched for crabs among the dense kelp just below the rocky shore.','海獭在岩岸下方茂密的巨藻丛中寻找螃蟹。','Sea otters searched for crabs / among the dense kelp / just below the rocky shore.','kelp 常作集合名词，指大型海藻；among 表示动物在海藻之间活动。','茂密海藻为螃蟹提供栖息处，海獭在其中觅食。'),M('The divers found a kelp forest growing in a hot, dry desert with no seawater.','The divers found a kelp forest growing in cool coastal seawater.','kelp 生长于海水中，尤其常见于凉冷近海，不会长在干燥沙漠。','meaning'),[Q('kelp',1,1,'Kelp is a type of?','large brown seaweed','small desert mammal','wooden boat beam','kelp 指大型褐藻。'),Q('kelp',2,1,'Where can kelp forests form?','in cold coastal waters','on dry inland roads','inside a courtroom','巨藻可在冷水近海形成海底森林。'),Q('kelp',3,1,'What did the otters search for among kelp?','crabs','keystrokes','wooden panels','海獭在巨藻中寻找螃蟹。'),Q('kelp',4,1,'Kelp is important because it can?','provide habitat for marine life','carry freight downstream','form the central stone of an arch','海藻林是海洋生物栖息地。')]);
P('ken','Ken 源自古英语 cennan 的相关词形，指一个人的知识或理解范围，也可古雅地指目力所及的视野。',[C('ken.s1','知识与理解','The details of quantum computing were beyond the museum guide’s ken, so she invited a specialist to answer visitors’ questions.','量子计算的细节超出了博物馆讲解员的知识范围，因此她请专家回答参观者的问题。','The details of quantum computing were beyond the museum guide’s ken / so she invited a specialist / to answer visitors’ questions.','beyond one’s ken 是固定表达，表示超出某人知识范围；so 引出应对方式。','讲解员无法理解该专业领域，于是请专家协助。',''),C('ken.s2','视野与目力','From the hilltop, the lighthouse remained within our ken even as mist covered the distant coast.','即使远岸被雾笼罩，山顶上的灯塔仍在我们的视野之内。','From the hilltop / the lighthouse remained within our ken / even as mist covered the distant coast.','ken 可古雅地表示目力所及；within one’s ken 表示在视野范围内。','灯塔仍可见，体现视野义。','')],M('The advanced equations were within the novice’s ken even though she had never studied mathematics and could not understand them.','The advanced equations were beyond the novice’s ken because she had not studied the subject.','不理解的内容超出某人的 ken，而不是在其认知范围内。'),[Q('ken',1,1,'Beyond someone’s ken means beyond their?','knowledge or understanding','weight limit','ability to steer a boat','beyond one’s ken 表示超出认知范围。'),Q('ken',2,2,'If a lighthouse is within your ken, it is?','within your field of sight','too heavy to carry','beyond all possible view','within one’s ken 可表示在视野之内。'),Q('ken',3,1,'Which phrase means “outside my understanding”?','beyond my ken','within my ken','on an even keel','beyond my ken 是超出我的认知。'),Q('ken',4,2,'In older usage, ken can refer to?','the range of sight','a unit of mass','a river freight boat','ken 也可古雅地指目力所及。')]);
P('kennel','Kennel 经古法语及盎格鲁法语词形进入英语，作名词指狗屋或寄养、繁殖狗的场所，作动词指把狗安置在狗舍中。',[C('kennel.s1','宠物照料','The rescue centre built a shaded kennel for each dog and placed fresh water beside every gate.','救助中心为每只狗搭建了有遮阴的狗舍，并在每个门边放了干净的水。','The rescue centre built a shaded kennel for each dog / and placed fresh water / beside every gate.','kennel 作名词指狗居住的小屋或狗舍；for each dog 标明用途。','给每只狗设置独立狗屋符合名词义。',''),C('kennel.s2','寄养与安置','The owners kennelled their two terriers while the apartment floors were being repaired.','公寓地板维修期间，主人把两只梗犬寄养在狗舍。','The owners kennelled their two terriers / while the apartment floors / were being repaired.','kennel 作及物动词表示把狗放在狗舍或寄养场；while 引出寄养原因。','装修期间把狗寄养，体现动词义。','')],M('The owners kennelled the terriers by releasing them to roam through the construction site without shelter.','The owners kennelled the terriers in a safe boarding facility during the repairs.','把狗留在安全狗舍与让它们在工地自由游荡相反。','context'),[Q('kennel',1,1,'A kennel is a shelter or facility for?','dogs','juniper trees','judo judges','kennel 指狗舍或养狗场所。'),Q('kennel',2,2,'If owners kennel their dogs, they?','put them in a dog shelter or boarding place','release them to roam through a worksite','teach them to type with a keyboard','kennel 作动词表示把狗安置在狗舍。'),Q('kennel',3,1,'Where might a dog sleep at night?','in a kennel beside the house','in the keel of a boat','in a kelp forest','狗舍是狗的栖身处。'),Q('kennel',4,2,'Which sentence uses kennel as a verb?','They kennelled the dogs during the renovation.','The kennel has a wooden roof.','The reporter wrote a keyword list.','第一句的 kennelled 是动词过去式。')]);
P('kerosene','Kerosene 是19世纪由石油化学家 Abraham Gesner 创造的名称，取希腊语 kēros“蜡”相关词根，指从石油提炼的煤油燃料。',C('kerosene.s1','燃料与照明','The remote cabin used a kerosene lamp when the storm knocked out its electricity.','暴风雨导致断电后，偏远小屋点起了煤油灯。','The remote cabin used a kerosene lamp / when the storm knocked out / its electricity.','kerosene 修饰 lamp，说明煤油是灯的燃料；when 引出使用场景。','断电后用煤油灯照明，符合煤油用途。'),M('The camping stove ran on kerosene, a dry solid wood that could not be poured into its fuel tank.','The camping stove ran on kerosene, a liquid petroleum fuel that could be poured into its tank.','kerosene 是液态石油燃料，不是固体木材。','meaning'),[Q('kerosene',1,1,'Kerosene is a fuel derived from?','petroleum','seaweed alone','wooden boat hulls','kerosene 是石油燃料。'),Q('kerosene',2,1,'Why did the cabin use a kerosene lamp?','the storm had cut the electricity','the cabin had no need for light','the lamp was filled with seawater','煤油灯在停电时用于照明。'),Q('kerosene',3,1,'Which item may burn kerosene?','a lamp or heater','a keyboard key','a dog kennel','煤油可用于灯具和取暖器。'),Q('kerosene',4,1,'British English may call kerosene?','paraffin','karma','kelp','英式英语常把煤油称为 paraffin。')]);
P('kestrel','Kestrel 经古法语 crecerelle 一类词形进入英语，指一种小型隼，常悬停在空中观察并捕食鼠类或昆虫。',C('kestrel.s1','猛禽观察','A kestrel hovered above the meadow, then dropped suddenly toward a mouse in the grass.','一只红隼悬停在草地上方，随后突然俯冲向草丛中的老鼠。','A kestrel hovered above the meadow / then dropped suddenly / toward a mouse in the grass.','kestrel 是小型隼类猛禽；then 标出先悬停、后俯冲的动作顺序。','悬停观察后捕捉老鼠，是红隼典型的捕食方式。'),M('The kestrel hunted by swimming underwater through kelp instead of flying above the meadow.','The kestrel hunted by hovering above the meadow and diving toward its prey.','kestrel 是飞行猛禽，不是水下游泳的海洋动物。','meaning'),[Q('kestrel',1,1,'A kestrel is a small?','falcon or bird of prey','brown seaweed','Australian marsupial','kestrel 是小型隼类猛禽。'),Q('kestrel',2,1,'How may a kestrel search for prey?','hovering in the air and watching below','digging through the seabed','building a keelboat','红隼常悬停观察猎物。'),Q('kestrel',3,1,'What prey might a kestrel catch?','a mouse or insect','a large whale','a wooden panel','红隼可捕食鼠类和昆虫。'),Q('kestrel',4,1,'Which action best identifies a kestrel?','hovering before a sudden dive','carrying a joey in a pouch','stewing meat in a covered pot','悬停后俯冲是红隼的常见捕猎方式。')]);
P('keystone','Keystone 由 key 与 stone 组成，原指拱券顶部锁定两侧石块的拱心石，后比喻理论、计划或体系赖以成立的关键部分。',[C('keystone.s1','建筑结构','The mason lifted the keystone into the crown of the arch, locking the neighboring stones in place.','石匠把拱心石安放到拱券顶端，将相邻石块锁定在位置上。','The mason lifted the keystone / into the crown of the arch / locking the neighboring stones in place.','keystone 作建筑名词指拱券顶部的楔形石；locking 补充其结构作用。','顶部石块锁定两边拱石，体现字面义。'),C('keystone.s2','计划与原则','Reliable public data is the keystone of the climate plan because every target depends on accurate measurement.','可靠的公共数据是气候计划的基石，因为每项目标都依赖准确测量。','Reliable public data is the keystone of the climate plan / because every target depends / on accurate measurement.','the keystone of 比喻某体系的关键组成；because 说明依赖关系。','各项目标都依赖数据，显示数据是计划核心。')],M('The architect removed the keystone from the arch but claimed it was the most important stone holding the structure together.','The architect kept the keystone in place because it locks the arch stones together.','移除拱心石会削弱拱结构，不能同时说它仍在锁定石块。','meaning'),[Q('keystone',1,1,'A keystone in an arch is?','the central wedge-shaped stone that locks the arch','a loose stone far below the bridge','a key pressed on a keyboard','拱心石位于拱顶并锁住两侧石块。'),Q('keystone',2,2,'Calling trust the keystone of an agreement means trust is?','essential to the agreement','a decorative detail with no effect','the last item added to the agreement','比喻义表示不可或缺的关键部分。'),Q('keystone',3,1,'What can happen if an arch keystone slips?','the arch may become unstable','the river changes direction immediately','a keyboard stops recording presses','拱心石松动会影响拱的稳定。'),Q('keystone',4,2,'Which phrase uses the figurative sense?','education is the keystone of the reform','the stone sat at the top of the arch','the mason measured a block','教育是改革的基石，属于比喻义。')]);
P('keystroke','Keystroke 由 key 与 stroke 组合，指在键盘或打字机上按下一次按键的动作。',C('keystroke.s1','计算机输入','The form saves its contents after each keystroke, so a brief power cut will not erase the whole application.','表格每次按键后都会保存内容，因此短暂断电不会抹掉整份申请。','The form saves its contents after each keystroke / so a brief power cut / will not erase the whole application.','keystroke 是一次按键动作；after each 表示每次输入之后。','每按一下就自动保存，符合按键事件的用法。'),M('The system recorded each keystroke even when the user never pressed a key.','The system recorded each keystroke when the user pressed a key.','keystroke 必须有实际按键动作。','meaning'),[Q('keystroke',1,1,'A keystroke is?','one press of a key','a word typed into a search box','a key left untouched on a desk','keystroke 指一次按键。'),Q('keystroke',2,1,'When did the form save its contents?','after every key press','only before the user opened it','after the keyboard was removed','例句中每次按键后都会保存。'),Q('keystroke',3,1,'Which is one keystroke?','pressing the letter A once','typing a full paragraph without counting','opening a kennel door','单按一次字母键就是一次 keystroke。'),Q('keystroke',4,1,'Keystroke is formed from?','key plus stroke','keystone plus stone','kelp plus stroke','keystroke 由 key 和 stroke 组合。')]);
P('keywords','Keywords 是 keyword 的复数，由 key 与 word 组合，指概括文章或主题、也可用于网络检索的关键词。',C('keywords.s1','检索与写作','The research team added keywords about coastal erosion so that the report would appear in relevant database searches.','研究团队添加了关于海岸侵蚀的关键词，让报告能出现在相关数据库检索结果中。','The research team added keywords about coastal erosion / so that the report would appear / in relevant database searches.','keywords 指概括主题或辅助检索的词；so that 表示添加关键词的目的。','关键词帮助数据库按主题检索报告。'),M('The author listed keywords unrelated to the report’s subject and expected them to improve relevant searches.','The author listed keywords that described the report’s subject to improve relevant searches.','与主题无关的词不能有效概括内容或帮助相关检索。','context'),[Q('keywords',1,1,'Keywords are words used to?','summarize a topic or help people search','describe the weight of a boat','name a dog shelter','关键词用于概括主题或检索。'),Q('keywords',2,1,'Why did the team add terms about coastal erosion?','to help the report appear in relevant searches','to make the report harder to find','to change the report into a keystone','关键词提高相关检索的可见性。'),Q('keywords',3,1,'What is the singular form of keywords?','keyword','keywordes','keyedword','keywords 的单数是 keyword。'),Q('keywords',4,1,'Which item is a set of keywords for a report on sea plants?','kelp, coastal habitat, marine ecology','judo, keyboard, court appeal','jubilant, jovial, judicious','描述海洋植物主题的词可作为关键词。')]);
P('killer','Killer 由 kill 加施事者后缀 -er 构成，可指造成死亡的人、动物或因素，也可口语指极难或极出色的事物。',[C('killer.s1','公共健康','The report identified air pollution as a major killer in cities where residents breathe unhealthy levels of fine particles.','报告指出，在居民吸入大量有害细颗粒物的城市，空气污染是主要致死因素。','The report identified air pollution as a major killer / in cities where residents breathe / unhealthy levels of fine particles.','killer 可指造成死亡的疾病或因素，不限于杀人者；as a major killer 作主语补语。','空气污染会致死，符合因素义。'),C('killer.s2','难题与挑战','The final coding question was a real killer, taking even the most experienced candidates nearly an hour to solve.','最后一道编程题确实难倒了人，连经验最丰富的考生也花了近一小时才解出。','The final coding question was a real killer / taking even the most experienced candidates / nearly an hour to solve.','口语中 a killer 可指非常难的事物；此处不是致死者。','题目耗时且难解，体现非正式“难题”义。')],M('The killer disease caused no deaths and posed no health risk to anyone exposed to it.','The killer disease caused many deaths and posed a serious health risk.','若疾病未造成死亡且无健康风险，就不能称为致死因素。','meaning'),[Q('killer',1,1,'A killer can be?','a person or factor that causes death','a word that summarizes a text','a safe shelter for a dog','killer 可指致死的人或因素。'),Q('killer',2,2,'A “killer exam question” informally means?','an extremely difficult question','a harmless easy question','a question about a dog kennel only','killer 可口语表示难度极高。'),Q('killer',3,1,'Why was air pollution called a killer?','it can cause deaths and serious disease','it helps everyone breathe clean air','it is a kind of bird of prey','污染造成疾病和死亡，符合致死义。'),Q('killer',4,2,'Which phrase uses the informal difficulty sense?','That last puzzle was a killer.','The killer was convicted of murder.','Heart disease is a major killer.','最后一句中的 killer 指难题。')]);
P('kilo','Kilo 是 kilogram 的日常简称，也可作为国际单位词头 kilo- 表示一千；此处词条主要作可数名词指一千克。',C('kilo.s1','重量与购物','The grocer weighed a kilo of lentils and packed it in a paper bag for the customer.','杂货店店员称了一千克扁豆，并把它装进纸袋交给顾客。','The grocer weighed a kilo of lentils / and packed it in a paper bag / for the customer.','a kilo of 表示一千克某物；kilo 作可数名词，复数 kilos。','称取一千克扁豆符合质量单位用法。'),M('The label said “one kilo,” but the package contained one thousand kilograms of lentils.','The label said “one kilo,” and the package contained one kilogram of lentils.','kilo 单独作名词表示一千克，不表示一千千克。','measurement'),[Q('kilo',1,1,'In everyday use, one kilo is?','one kilogram','one kilometre','one hundred grams','kilo 常是 kilogram 的简称。'),Q('kilo',2,1,'How much lentils did the grocer weigh?','one kilogram','one litre','one thousand kilograms','a kilo of lentils 是一千克扁豆。'),Q('kilo',3,1,'What does the prefix kilo- mean in kilometre?','one thousand','one hundredth','one million','kilo- 作为词头表示一千。'),Q('kilo',4,1,'What is the usual plural of the noun kilo?','kilos','kiloes','kilosses','名词 kilo 的常见复数是 kilos。')]);
P('kilogramme','Kilogramme 是英国常见的 kilogram 拼法，由 kilo-“千”与 gram 组合，指质量单位千克，符号为 kg。',C('kilogramme.s1','质量与计量','The laboratory balance showed that the sample weighed exactly one kilogramme, or one thousand grams.','实验室天平显示，样品正好重一千克，也就是一千克即一千克质量单位。','The laboratory balance showed / that the sample weighed exactly one kilogramme / or one thousand grams.','kilogramme 指一千克，等于 1000 克；英式拼法多出一个 -me。','例句中的等值换算说明质量单位的含义。'),M('The box weighed one kilogramme, meaning it had a mass of one kilometre.','The box weighed one kilogramme, meaning it had a mass of one thousand grams.','kilogramme 是质量单位，不是长度单位 kilometre。','confusable'),[Q('kilogramme',1,1,'A kilogramme is a unit of?','mass equal to 1,000 grams','distance equal to 1,000 metres','temperature','kilogramme 表示 1000 克的质量。'),Q('kilogramme',2,1,'What spelling is common in British English?','kilogramme','kilogramm','kilogrammees','英国英语常见拼法是 kilogramme。'),Q('kilogramme',3,1,'What symbol is used for the kilogram?','kg','km','kl','千克的国际单位符号是 kg。'),Q('kilogramme',4,1,'Which word can mean one kilogramme informally?','kilo','kilo- as a verb','keel','kilo 可作为 kilogramme 的日常简称。')]);
P('kinda','Kinda 是 kind of 的口语弱读拼写，表示“有点儿、在一定程度上”，适合对话和非正式写作。',C('kinda.s1','口语评价','The documentary was kinda slow at first, but the final interviews made it worthwhile.','这部纪录片一开始有点慢，不过最后的采访让它值得一看。','The documentary was kinda slow at first / but the final interviews / made it worthwhile.','kinda 是非正式副词，表示 somewhat；正式文章可改用 kind of 或 rather。','说话者认为节奏有些慢但不是完全乏味。'),M('The grant proposal used “kinda” as a formal technical term in its definitions section.','The grant proposal used “somewhat” in its formal definitions section.','kinda 是口语弱读形式，不适合作正式技术定义用词。','register'),[Q('kinda',1,1,'Kinda is an informal form of?','kind of','kinship','kilo of','kinda 是 kind of 的口语形式。'),Q('kinda',2,1,'“The film was kinda slow” means it was?','somewhat slow','completely silent','a measure of distance','kinda 表示有点儿、在一定程度上。'),Q('kinda',3,1,'Which is better in formal writing?','somewhat','kinda','kinda sorta','正式文体宜用 somewhat。'),Q('kinda',4,1,'Kinda is most suitable in?','casual conversation','a formal scientific definition','a legal statute','kinda 属于非正式口语。')]);
P('kinematics','Kinematics 源自希腊语 kinēma“运动”及 -ics 学科后缀，指描述物体位置和运动、但不研究造成运动之力的力学分支。',C('kinematics.s1','物理课程','The mechanics course covered kinematics first, calculating position and speed before discussing forces.','力学课程先讲运动学，计算位置和速度，再讨论作用力。','The mechanics course covered kinematics first / calculating position and speed / before discussing forces.','kinematics 描述运动状态；物体运动的成因和力属于动力学话题。','先算位置和速度、后讨论力，体现运动学与动力学的范围差异。'),M('The lecturer defined kinematics as the study of forces causing motion, without describing position or speed.','The lecturer defined kinematics as the description of motion, position, and speed without analyzing its causes.','研究运动成因和作用力更接近动力学，而不是运动学。','distinction'),[Q('kinematics',1,1,'Kinematics describes?','motion without focusing on the forces that cause it','only the chemical makeup of a material','the legal authority of a court','运动学描述运动，不重点分析力的成因。'),Q('kinematics',2,1,'Which topic belongs to kinematics?','a particle’s position and speed over time','the force causing each acceleration only','the mass of a kilogramme standard only','位置和速度的变化是运动学内容。'),Q('kinematics',3,1,'Which field more directly studies forces?','dynamics','kinematics','kinship','力通常由动力学研究。'),Q('kinematics',4,1,'Kinematics is a branch of?','mechanics','botany','journalism','运动学是力学的一个分支。')]);
P('kinetic','Kinetic 源自希腊语 kinētikos“与运动有关”，经拉丁语和法语进入英语，形容运动的或由运动产生的。',C('kinetic.s1','物理与能量','The moving cart gained kinetic energy as it rolled faster down the gentle slope.','小车沿缓坡滚下、速度越来越快，获得了动能。','The moving cart gained kinetic energy / as it rolled faster / down the gentle slope.','kinetic energy 指物体因运动而具有的能量；as 引出速度变化过程。','小车运动加快，动能增加。'),M('The stationary cart had kinetic energy because it was completely motionless and had no movement.','The rolling cart had kinetic energy because it was moving.','完全静止的物体没有由其运动产生的动能。','meaning'),[Q('kinetic',1,1,'Kinetic energy is energy associated with?','motion','family relationships','the ringing of funeral bells','kinetic 与运动相关。'),Q('kinetic',2,1,'Why did the cart gain kinetic energy?','it rolled faster down the slope','it remained completely still','it was weighed in a kennel','运动速度增加，动能随之增加。'),Q('kinetic',3,1,'Potential energy is often contrasted with?','kinetic energy','kinship','kitchenware','势能常与动能相对。'),Q('kinetic',4,1,'Kinetic is an adjective related to?','movement','judgment','a dog shelter','kinetic 是“运动的”形容词。')]);
P('kinetoscope','Kinetoscope 是爱迪生实验室推广的早期电影观看设备名称，以希腊语 kinēt-“运动”与 skopein“观看”构词，供单人从观察孔观看胶片。',C('kinetoscope.s1','电影技术史','At the fair, each visitor leaned over the kinetoscope and watched a short film through its viewing slot.','在集市上，每位参观者俯身透过活动视镜的观察孔看一段短片。','At the fair / each visitor leaned over the kinetoscope / and watched a short film through its viewing slot.','kinetoscope 指早期单人电影观看装置；viewing slot 指供一人观看的观察孔。','观众依次透过观察孔观看短片，符合该装置使用方式。'),M('The crowd watched a projected film together on a large screen inside the single-viewer kinetoscope.','One visitor watched the moving film through the kinetoscope’s individual viewing slot.','kinetoscope 一次供一人观看，不是多人共同看大型投影幕。','distinction'),[Q('kinetoscope',1,1,'A kinetoscope was an early device for?','viewing a short moving film through a slot','weighing a kilogramme sample','measuring a keel’s length','kinetoscope 是早期电影观看装置。'),Q('kinetoscope',2,1,'How many people typically viewed a kinetoscope at once?','one','an entire theater audience','no one because it had no screen','该装置通常供一人观看。'),Q('kinetoscope',3,1,'What did the visitor look through?','a viewing slot','a telescope aimed at Jupiter','a keyhole in a kennel','观众透过观察孔看胶片。'),Q('kinetoscope',4,1,'What technology replaced peep-show viewing for groups?','projected films on a shared screen','a hand-held knapsack','a moving keelboat','放映机使多人能同时观看。')]);
P('kinfolk','Kinfolk 由 kin“亲属”与 folk“人们”组合，尤见于美式英语，作集合名词指家人和亲戚。',C('kinfolk.s1','家庭与社区','Her kinfolk travelled from three states to help prepare the hall for the family reunion.','她的亲戚从三个州赶来，帮忙为家庭团聚布置大厅。','Her kinfolk travelled from three states / to help prepare the hall / for the family reunion.','kinfolk 指亲属群体，常按集合名词使用；from 引出亲人来源地。','多地亲属一同参加家庭团聚。'),M('She invited her kinfolk, meaning strangers who had no family or personal connection to her.','She invited her kinfolk, meaning relatives from both sides of her family.','kinfolk 指家人或亲戚，不是无关陌生人。','meaning'),[Q('kinfolk',1,1,'Kinfolk means a person’s?','relatives or family members','neighbors with no connection','court-appointed judges','kinfolk 指亲属。'),Q('kinfolk',2,1,'Who came to the family reunion?','relatives from several states','only unrelated tourists','a group of kestrels','例句写亲戚从多地前来。'),Q('kinfolk',3,1,'Kinfolk is especially associated with?','American English','formal chemical naming','ancient Roman law only','kinfolk 尤常见于美式英语。'),Q('kinfolk',4,1,'Which word is closest in meaning to kinfolk?','relatives','keystrokes','kestrels','relatives 与 kinfolk 意义接近。')]);
P('kinglet','Kinglet 由 king 加表示小的 -let 构成，可指小国君主，也可指戴菊属的一种小型鸣禽。',[C('kinglet.s1','政治与历史','The emperor treated the neighbouring kinglet as a minor ruler and demanded an annual tribute.','皇帝把邻国的小国君主视作低阶统治者，并要求其每年进贡。','The emperor treated the neighbouring kinglet as a minor ruler / and demanded / an annual tribute.','kinglet 作名词指小国或弱国的君主，有时略带轻蔑。','邻国统治者被视为次要君主。'),C('kinglet.s2','鸟类观察','A golden-crowned kinglet flicked through the spruce branches, searching for insects in the cold morning.','一只金冠戴菊在云杉枝间快速穿梭，在寒冷的早晨寻找昆虫。','A golden-crowned kinglet flicked through the spruce branches / searching for insects / in the cold morning.','kinglet 也指戴菊属的小型鸣禽；golden-crowned 是鸟类名的一部分。','云杉间活动并觅食的小鸟对应鸟类义。')],M('The bird guide identified the tiny golden-crowned kinglet as a large flightless marsupial.','The bird guide identified the tiny golden-crowned kinglet as a small songbird.','kinglet 的鸟类义是小型鸣禽，不是有袋动物。','meaning'),[Q('kinglet',1,1,'A kinglet may be a ruler of?','a small or weak kingdom','the Roman gods','all of the solar system','kinglet 可指小国君主。'),Q('kinglet',2,2,'A golden-crowned kinglet is a?','tiny songbird','small marsupial','brown seaweed','鸟类义指戴菊等小型鸣禽。'),Q('kinglet',3,1,'Why did the emperor call his neighbour a kinglet?','he ruled a small, dependent kingdom','he was the emperor’s eldest son','he was a bird living in a spruce','小国统治者可称 kinglet。'),Q('kinglet',4,2,'Which context uses kinglet for a bird?','A kinglet searched spruce branches for insects.','The kinglet negotiated a treaty with the emperor.','The kinglet issued a court judgment.','在树枝上觅食的是鸟类义。')]);
P('kink','Kink 的词源不确定；作名词指绳、线或软管上的紧急扭结，也可作动词表示形成这种扭结。',[C('kink.s1','管线与故障','A kink in the garden hose stopped the water from reaching the far end of the vegetable bed.','花园水管上有个急弯，水无法流到菜畦远端。','A kink in the garden hose / stopped the water / from reaching the far end of the vegetable bed.','kink 作名词指绳线或软管上的急弯、扭结；stop A from doing 表示阻止。','扭结使水流不畅，符合名词义。'),C('kink.s2','形状变化','The cable kinked when it was wound too tightly around the small reel.','电缆在小卷轴上绕得太紧，扭出了结。','The cable kinked / when it was wound too tightly / around the small reel.','kink 作动词，表示绳线因扭转而形成急弯；此处为不及物用法。','电缆过紧缠绕后形成扭结。')],M('The hose had no kink and water flowed freely, but the gardener said the kink was blocking the water.','The hose had a kink that bent sharply and blocked the water flow.','若水管没有扭结且水流通畅，就不能说扭结堵住水流。','meaning'),[Q('kink',1,1,'A kink in a hose is?','a sharp twist or bend that may block flow','a smooth straight section','a small king’s kingdom','kink 指急弯或扭结。'),Q('kink',2,2,'If a cable kinked, it?','formed a tight twist','became perfectly straight','was weighed in kilos','kink 作动词表示扭成结。'),Q('kink',3,1,'What happened when the garden hose kinked?','water could not reach the far end','the water moved faster than before','the hose turned into a kelp plant','扭结阻碍水流。'),Q('kink',4,2,'Which phrase can use the figurative noun kink?','a kink in the plan','a kilogramme of the plan','a kinfolk of the plan','kink 也可比喻计划中的小波折。')]);
P('kinship','Kinship 由 kin 加 -ship 构成，指亲属关系，也可指因共同特征、经历或命运而产生的亲近感。',[C('kinship.s1','亲属制度','The anthropologist mapped kinship through the mother’s line to understand how family obligations passed between generations.','人类学家沿母系梳理亲属关系，以了解家庭责任如何代际传递。','The anthropologist mapped kinship through the mother’s line / to understand / how family obligations passed between generations.','kinship 作不可数名词指亲属关系；through the mother’s line 表示母系。','分析亲属关系与责任传递是人类学研究内容。',''),C('kinship.s2','共同经历与归属','After sharing long night shifts, the nurses felt a strong kinship with one another.','共同经历漫长夜班后，护士们彼此产生了强烈的亲近感。','After sharing long night shifts / the nurses felt a strong kinship / with one another.','kinship 可表示人与人之间的亲近或同类感；with 引出对象。','共同经历让护士感到彼此相似、有连结。')],M('The nurses felt kinship with one another despite believing they shared nothing and had no sense of connection.','The nurses felt a sense of kinship because they shared difficult night shifts.','完全没有共同点或连结感与此处亲近义相反。','context'),[Q('kinship',1,1,'Kinship can refer to?','family relationships','the weight of a package','a type of sea bird','kinship 可指亲属关系。'),Q('kinship',2,2,'A feeling of kinship means?','a sense of connection or affinity','a desire to avoid everyone','a sharp bend in a hose','kinship 也表示亲近感。'),Q('kinship',3,1,'What did the anthropologist study?','relationships through the mother’s line','how much kerosene a lamp uses','how a kestrel catches mice','例句关注母系亲属关系。'),Q('kinship',4,2,'Kinship with night-shift workers arose from?','shared experience','a court ruling','a keyboard press','共同的夜班经历带来亲近感。')]);
P('kiosk','Kiosk 经土耳其语 köşk 和波斯语相关词形经法语进入英语，指街道、车站或公园里的小型售货亭或服务亭。',C('kiosk.s1','车站与零售','We bought two train tickets at the kiosk beside the station entrance.','我们在车站入口旁的小亭买了两张火车票。','We bought two train tickets / at the kiosk / beside the station entrance.','kiosk 指小型售货或服务亭；at 标明买票地点。','车站售票亭符合 kiosk 的常见场景。'),M('They bought newspapers at the kiosk, which was a large department store covering several city blocks.','They bought newspapers at the kiosk, a small street-side stall.','kiosk 指小亭或小型柜台，不是占几个街区的大型百货商店。','meaning'),[Q('kiosk',1,1,'A station kiosk is usually?','a small booth selling tickets or refreshments','a large underground railway tunnel','a courtroom used for trials','kiosk 是小型售货亭或服务亭。'),Q('kiosk',2,1,'What did the travelers buy at the kiosk?','train tickets','a kilogramme of stone','a kestrel nest','例句中他们在小亭买车票。'),Q('kiosk',3,1,'Where might an information kiosk stand?','in a station or public park','inside a moving keelboat only','in a kelp forest','问讯亭常设在车站、公园等公共场所。'),Q('kiosk',4,1,'Kiosk most nearly means?','small booth or stall','large palace','family relationship','kiosk 意为小亭、售货亭。')]);
P('kitchenware','Kitchenware 由 kitchen 与 ware“制品、用品”组成，作不可数集合名词指厨房里准备和烹饪食物使用的器具。',C('kitchenware.s1','购物与家居','The store moved its kitchenware to the ground floor, where customers could compare the pans and mixing bowls.','商店把厨具移到一楼，顾客可以在那里比较平底锅和搅拌碗。','The store moved its kitchenware to the ground floor / where customers could compare / the pans and mixing bowls.','kitchenware 指厨房器具集合，通常不可数；where 引出购物区域。','锅和平底碗都是厨房用具的实例。'),M('The shop sold kitchenware, but every item was a coat, a pair of boots, or a scarf.','The shop sold kitchenware such as pans, bowls, and cooking tools.','衣物和鞋子不属于厨房用具。','meaning'),[Q('kitchenware',1,1,'Kitchenware includes?','pots, pans, bowls, and cooking tools','only outdoor shoes and coats','boats and their keels','kitchenware 指厨房用具。'),Q('kitchenware',2,1,'Where did the shop move the kitchenware?','to the ground floor','into a river keelboat','above a sea cliff','例句说明厨具移到一楼。'),Q('kitchenware',3,1,'Kitchenware is usually treated as?','an uncountable collective noun','a plural verb','a name for one kitchen room','kitchenware 通常作不可数集合名词。'),Q('kitchenware',4,1,'Which item is kitchenware?','a mixing bowl','a kestrel','a knapsack','搅拌碗属于厨房用品。')]);
P('kittiwake','Kittiwake 是模仿这种海鸟叫声的拟声名称，指常在海崖筑巢、翼尖黑色的三趾鸥。',C('kittiwake.s1','海鸟与栖地','Kittiwakes gathered on the narrow cliff ledges above the waves to feed their chicks.','三趾鸥聚集在海浪上方狭窄的悬崖岩架上，为幼鸟觅食。','Kittiwakes gathered on the narrow cliff ledges / above the waves / to feed their chicks.','kittiwake 指海崖筑巢的鸥类；to feed 表示聚集的目的。','在海崖岩架筑巢并喂养幼鸟符合三趾鸥习性。'),M('The kittiwake nested in a dry desert burrow and had no wings or feathers.','The kittiwake nested on a sea cliff and used its wings to fly above the water.','kittiwake 是有翼羽的海鸟，不会在沙漠地洞中筑巢。','meaning'),[Q('kittiwake',1,1,'A kittiwake is a kind of?','gull that nests on sea cliffs','marsupial that carries a joey','brown seaweed','kittiwake 是海崖筑巢的鸥。'),Q('kittiwake',2,1,'Where did the birds gather?','on cliff ledges above the waves','inside a kennel','on a keyboard','例句中三趾鸥聚在海崖岩架。'),Q('kittiwake',3,1,'The name kittiwake imitates?','the bird’s call','the sound of a keystroke','a Roman god’s voice','kittiwake 是拟声词。'),Q('kittiwake',4,1,'What do kittiwakes feed?','their chicks','judo students','a boat’s keel','例句说明成年鸟为幼鸟觅食。')]);
P('kiwi','Kiwi 借自毛利语，既指新西兰不会飞的夜行鸟，也可指猕猴桃；大写 Kiwi 还可作新西兰人的非正式称呼。',[C('kiwi.s1','新西兰鸟类','The kiwi used its long bill to probe the damp soil for insects after sunset.','日落后，几维鸟用长喙探入潮湿土壤寻找昆虫。','The kiwi used its long bill / to probe the damp soil / for insects after sunset.','kiwi 指新西兰不会飞的鸟；to probe 表示用喙探查土壤。','长喙夜间探土觅食符合几维鸟习性。'),C('kiwi.s2','水果与饮食','She peeled a kiwi and added the bright green slices to a bowl of yoghurt.','她剥开一只猕猴桃，把鲜绿色的果片加进一碗酸奶里。','She peeled a kiwi / and added the bright green slices / to a bowl of yoghurt.','kiwi 可作可数名词指猕猴桃；peeled 和 slices 是水果食用场景。','剥皮并切片加入酸奶，体现水果义。')],M('She peeled a kiwi, expecting a bird with feathers and a long bill inside the fruit.','She peeled a kiwi fruit and added its green flesh to the yoghurt.','kiwi 作水果时指猕猴桃，不是鸟；不要把两个词义混为一谈。','confusable'),[Q('kiwi',1,1,'A kiwi bird is?','a flightless bird native to New Zealand','a large Roman planet','a small sea gull','kiwi 可指新西兰不会飞的鸟。'),Q('kiwi',2,2,'She peeled a kiwi and added it to yoghurt. Here kiwi means?','a green-fleshed fruit','a nocturnal bird','a New Zealand person','剥皮切片加入酸奶，说明是猕猴桃。'),Q('kiwi',3,1,'What does the bird use its long bill to do?','probe soil for food','build a keelboat','press keys on a keyboard','几维鸟用长喙探土觅食。'),Q('kiwi',4,2,'Which use of kiwi is about food?','a sliced kiwi in a fruit salad','a kiwi probing the forest floor','a Kiwi arriving from Wellington','切片放入水果沙拉的是猕猴桃。')]);
P('knap','Knap 源自古英语及日耳曼语中“敲击”相关词形，作动词指敲打燧石使其剥落成工具，也可作名词指一次猛击。',[C('knap.s1','石器制作','The archaeologist demonstrated how early toolmakers knapped flint into sharp cutting blades.','考古学家演示早期制作者如何把燧石敲制成锋利的切割刃。','The archaeologist demonstrated / how early toolmakers knapped flint / into sharp cutting blades.','knap 作及物动词，指敲石剥片制成工具；knapped 是过去式。','敲击燧石形成锐利刃片是打制石器。',''),C('knap.s2','敲击声与动作','With one quick knap of the hammerstone, a thin flint flake broke away from the core.','石锤迅速敲了一下，一片薄燧石片便从石核上剥落。','With one quick knap of the hammerstone / a thin flint flake broke away / from the core.','knap 作名词指一次敲击；with 引出导致石片剥落的动作。','石锤的一击使燧石剥落，体现名词义。')],M('The toolmaker knapped the flint by leaving it untouched until it shaped itself into a blade.','The toolmaker knapped the flint by striking it to remove sharp flakes.','打制石器需要敲击剥片，不是放置不动让其自行成形。','meaning'),[Q('knap',1,1,'To knap flint is to?','strike it so flakes break off and form a tool','polish it without removing any material','weigh it in kilograms','knap flint 指敲击剥片制作石器。'),Q('knap',2,2,'A knap of the hammerstone is?','one sharp blow','a long written report','a family relationship','名词 knap 可指一次敲击。'),Q('knap',3,1,'What did the archaeologist demonstrate?','making a blade by striking flint','building a kennel','measuring kinematics','例句演示敲燧石制刃。'),Q('knap',4,1,'Which sound-alike word is knap pronounced like?','nap','knee','knell','knap 中的 k 不发音，与 nap 同音。')]);
P('knapsack','Knapsack 经荷兰语 knapzak 一类词形进入英语，指用肩带背在背上的包，常见于徒步、旅行或军旅语境。',C('knapsack.s1','徒步与装备','The hikers packed a map, a first-aid kit, and two bottles of water into each knapsack.','徒步者把地图、急救包和两瓶水装进每个背包。','The hikers packed a map, a first-aid kit, and two bottles of water / into each knapsack.','knapsack 指用肩带背在背上的包；pack ... into 表示把物品装入。','徒步者把补给装入背包符合该词义。'),M('The hikers stored their supplies in a knapsack, a small shelter built beside a kennel.','The hikers stored their supplies in a knapsack, a bag worn on the back with shoulder straps.','knapsack 是背包，不是狗舍旁的小屋。','meaning'),[Q('knapsack',1,1,'A knapsack is?','a bag carried on the back with straps','a small gull nesting on a cliff','a type of kitchen pan','knapsack 指背在背上的包。'),Q('knapsack',2,1,'What did the hikers pack into their knapsacks?','maps, a first-aid kit, and water','a Roman temple','a keel from a boat','例句列举了徒步用品。'),Q('knapsack',3,1,'Which activity commonly uses a knapsack?','hiking','judo judging','measuring a keystroke','徒步者常背 knapsack。'),Q('knapsack',4,1,'Which word is a common modern synonym?','backpack','kittiwake','kinship','backpack 与 knapsack 意思接近。')]);
P('knell','Knell 源自古英语 cnyllan“敲钟”，作名词指为死亡或葬礼缓慢敲响的钟声，也常比喻某事的终结信号；作动词指敲丧钟。',[C('knell.s1','比喻终结','The factory closure sounded the death knell for the small town’s last major employer.','工厂关闭敲响了这座小镇最后一家大型雇主的丧钟。','The factory closure sounded the death knell / for the small town’s last major employer.','death knell 是固定比喻，表示某事走向终结的信号；for 引出受影响对象。','最后大型雇主关闭意味着当地产业衰退。',''),C('knell.s2','钟声与葬礼','Church bells knelled slowly across the valley as the funeral procession entered the village.','葬礼队伍进入村庄时，教堂的钟声在山谷间缓慢回荡。','Church bells knelled slowly across the valley / as the funeral procession / entered the village.','knell 作动词表示为葬礼缓慢敲钟；as 表示钟声与队伍进入同时发生。','葬礼时缓慢敲响教堂钟声，体现字面动词义。')],M('The newspaper called the new contract the death knell of the factory, although it guaranteed the factory’s expansion and long-term survival.','The newspaper called the factory closure the death knell because it ended the company’s local operations.','保障扩张与长期经营的合同不是工厂终结的信号。','meaning'),[Q('knell',1,1,'A death knell is?','a sign that something is ending','a cheerful wedding song','a type of bird call','death knell 比喻终结信号。'),Q('knell',2,2,'When bells knell, they?','ring slowly, especially for a funeral','flash without making any sound','form a sharp twist in a hose','knell 作动词指缓慢敲钟。'),Q('knell',3,1,'Why was the factory closure a death knell?','it ended the town’s last major employer','it guaranteed many new jobs','it opened a new museum','关闭工厂意味着最后的大型雇主消失。'),Q('knell',4,2,'Which is the literal use of knell?','Bells knelled during the funeral.','The scandal was the death knell of his career.','A kink formed in the hose.','葬礼钟声是 knell 的字面用法。')]);
P('knuckle','Knuckle 的词源不确定，作名词指手指关节，尤其是手指与手掌相接处；作动词可指用指节触压，也见于 knuckle down“认真苦干”。',[C('knuckle.s1','身体与动作','He rapped his knuckles on the wooden desk to get the students’ attention.','他用指节敲了敲木桌，以引起学生们的注意。','He rapped his knuckles on the wooden desk / to get the students’ attention.','knuckles 是指关节；rap one’s knuckles on 表示用指节轻敲。','用手指关节敲桌子符合名词义。',''),C('knuckle.s2','短语动词与工作','With the deadline approaching, the design team knuckled down and finished the safety review.','截止日期临近，设计团队开始认真工作，完成了安全审查。','With the deadline approaching / the design team knuckled down / and finished the safety review.','knuckle down 是短语动词，表示开始认真投入工作；过去式 knuckled down。','团队集中精力完成审查，体现短语义。')],M('The team knuckled down by abandoning the safety review and spending the day avoiding all work.','The team knuckled down by focusing on the safety review and completing it before the deadline.','逃避工作与 knuckle down 的“认真干起来”相反。','meaning'),[Q('knuckle',1,1,'A knuckle is?','a joint of a finger','a joint in a wooden arch','a unit of mass','knuckle 指手指关节。'),Q('knuckle',2,2,'To knuckle down is to?','begin working seriously','give up and avoid the task','press a key once','knuckle down 表示认真开始做事。'),Q('knuckle',3,1,'What did he use to rap on the desk?','his knuckles','a juniper berry','a steel keel','用指节敲桌子。'),Q('knuckle',4,2,'Which sentence uses knuckle as a noun?','She bruised a knuckle on the door.','They knuckled down to finish the report.','The cable kinked near the wall.','第一句中的 knuckle 是名词“指关节”。')]);
P('koala','Koala 借自澳大利亚原住民 Dharug 语 gula 一类词形，指生活在澳洲树上的有袋动物，以桉树叶为食，并非熊。',C('koala.s1','澳洲野生动物','The koala rested in the fork of a eucalyptus tree after feeding on leaves through the night.','考拉整夜吃桉树叶后，躺在桉树枝杈间休息。','The koala rested in the fork of a eucalyptus tree / after feeding on leaves / through the night.','koala 是树栖有袋动物；after feeding 表示进食后休息。','生活在桉树上并以其叶为食，符合考拉习性。'),M('The koala was a true bear that hunted fish and carried its cub in a hard eggshell.','The koala was a tree-dwelling marsupial that fed mainly on eucalyptus leaves.','考拉不是熊，不捕猎鱼类，也不以硬壳卵繁殖。','meaning'),[Q('koala',1,1,'A koala is a?','marsupial native to Australia','small European songbird','large brown seaweed','考拉是澳大利亚有袋类动物。'),Q('koala',2,1,'What does a koala mainly eat?','eucalyptus leaves','krill','juniper wood','考拉主要吃桉树叶。'),Q('koala',3,1,'Where might a koala rest?','in a tree fork','inside a kiosk','under a keelboat','考拉常在树上休息。'),Q('koala',4,1,'Why is “koala bear” misleading?','a koala is a marsupial, not a bear','koalas live only in the sea','koalas are birds of prey','koala bear 是俗称，分类上并非熊。')]);
P('krill','Krill 借自挪威语 krill“幼鱼、鱼苗”，指海洋中成群生活、形似小虾的浮游甲壳动物。',C('krill.s1','海洋食物链','Blue whales filter enormous swarms of krill from the water during their feeding season.','蓝鲸在觅食季节从海水中过滤大量磷虾群。','Blue whales filter enormous swarms of krill / from the water / during their feeding season.','krill 指小型海生甲壳动物；swarm 强调成群，filter ... from water 描述进食方式。','鲸过滤海水中的磷虾群，符合海洋食物链关系。'),M('The blue whale fed on krill, which are large land mammals living in eucalyptus trees.','The blue whale fed on krill, which are tiny sea-dwelling crustaceans.','磷虾是微小海洋甲壳动物，不是陆生哺乳动物。','meaning'),[Q('krill',1,1,'Krill are tiny sea animals resembling?','shrimp','koalas','kestrels','磷虾是形似小虾的海洋甲壳动物。'),Q('krill',2,1,'What did blue whales filter from the water?','swarms of krill','kitchenware','keystrokes','蓝鲸以海水中的磷虾为食。'),Q('krill',3,1,'Krill are important in the diet of?','whales and some penguins','jovial editors','small Roman rulers','鲸和部分企鹅会吃磷虾。'),Q('krill',4,1,'Krill most often live?','in huge groups in the sea','inside a dog kennel','on a dry mountain road','磷虾在海洋中大量群聚。')]);
P('krypton','Krypton 源自希腊语 kryptos“隐藏的”，因这种稀有气体难以从空气中分离而得名，元素符号为 Kr。',C('krypton.s1','化学元素','The chemistry students identified krypton in the sealed tube by comparing its emission spectrum with a reference chart.','化学专业学生把密封管中的氪与参考图谱对比，通过发射光谱辨认出它。','The chemistry students identified krypton in the sealed tube / by comparing its emission spectrum / with a reference chart.','krypton 是稀有气体元素，符号 Kr；by comparing 说明鉴别方法。','发射光谱可用于识别密封管中的元素。'),M('The label said krypton, but the tube contained liquid water and had the chemical symbol H₂O.','The label said krypton, and the tube contained the noble gas with symbol Kr.','krypton 是元素 Kr，不是水 H₂O。','confusable'),[Q('krypton',1,1,'Krypton is a?','colourless noble gas with symbol Kr','liquid metal with symbol K','green fruit with symbol Kiwi','krypton 是符号 Kr 的稀有气体。'),Q('krypton',2,1,'Why was the gas called krypton?','its name relates to being hidden or hard to isolate','it was first found in a dog kennel','it is named after a Roman king','krypton 来自希腊语“隐藏”相关词。'),Q('krypton',3,1,'Which symbol represents krypton?','Kr','K','Ky','氪的元素符号是 Kr。'),Q('krypton',4,1,'Krypton belongs to which chemical family?','noble gases','alkali metals','halogens','氪属于稀有气体。')]);

})();
